-- ------------------------------------------------------------------------------
-- [37/208] MIGRATION: 20260730160000_firm_scope_rls_framework.sql
-- ------------------------------------------------------------------------------

-- P0 fix: 36 of the 37 flagged core business tables enforce "signed in" but
-- not "same firm" on
-- RLS (USING (auth.uid() IS NOT NULL) from 20260619232538) — any
-- authenticated user can read/write any other firm's orders, invoices,
-- gold_ledger, KYC documents, etc.
--
-- Cannot backfill user_profiles.firm_id or create an organizations row here:
-- live data has 0 rows in organizations, 0 in user_profiles, and the one
-- branches row has firm_id NULL — there is no authoritative source to derive
-- a firm assignment from without fabricating one. That backfill + the actual
-- tenant-onboarding decision is explicitly left to Codex (see
-- CLAUDE_BACKEND_REVIEW_AND_HANDOVER.md).
--
-- What this migration does instead: makes every one of these 37 tables'
-- policies check firm_id, with a safe fallback for the current
-- everything-is-NULL state — `firm_id IS NULL AND my_firm_id() IS NULL`
-- still matches today (no lockout), and the moment a user_profiles row gets
-- a real firm_id and existing data gets backfilled to match, this becomes
-- real per-firm isolation with zero further RLS changes needed.
--
-- saas_admin always passes — platform role, deliberately not firm-scoped.
--
-- user_profiles (the 37th flagged table) is deliberately EXCLUDED here: its
-- live policies ("Users see own profile", "Users update own profile",
-- "Service role can insert profiles") already correctly check
-- auth_id = auth.uid() OR firm_id = my_firm_id(), and a blanket drop+replace
-- would remove the self-access and signup-insert paths this table actually
-- needs. Left untouched.

-- 1) Add firm_id (nullable, non-destructive) to the 8 tables that don't have it yet.
ALTER TABLE public.branch_settings ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.crm_interactions ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.crm_leads_opportunities ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.crm_tasks_meetings ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.gold_settlements ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.invitations ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.manufacturing_bills ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.melt_jobs ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;

-- 2) Rewrite the staff-write/no-viewer-write policy set (from 20260619232538)
-- on all 37 tables to add the firm_id check, keeping the viewer-write
-- restriction and read-for-any-signed-in-user behaviour otherwise unchanged.
DO $$
DECLARE
  t text;
  pol text;
  tables text[] := ARRAY[
    'rate_cut_records','gold_ledger','whatsapp_inbox','daily_close','print_logs','salary_rules',
    'worker_transactions','jeweller_transactions','whatsapp_templates','dropdown_masters','app_settings',
    'crm_tasks_meetings','inventory','kyc_documents','stock_movements','people','gold_settlements',
    'crm_interactions','melt_jobs','branch_settings','invitations','repairs','job_process_steps',
    'customer_ledger','communication_logs','job_cards','attendance','manufacturing_bills',
    'attachments','invoices','payments','catalog_designs','document_sequences','worker_settlements',
    'orders','crm_leads_opportunities'
  ];
  same_firm text := '(firm_id = public.my_firm_id() OR (firm_id IS NULL AND public.my_firm_id() IS NULL) OR public.has_role(auth.uid(), ''saas_admin''::public.app_role))';
BEGIN
  FOREACH t IN ARRAY tables LOOP
    IF to_regclass('public.' || t) IS NULL THEN
      CONTINUE;
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = t AND column_name = 'firm_id'
    ) THEN
      CONTINUE;
    END IF;
    -- Drop EVERY existing policy on this table, not just ones matching our
    -- naming convention — different tables in this list got their permissive
    -- policy from different migrations (20260619232538 vs. others), under
    -- different policy names. Postgres OR's multiple permissive policies
    -- together, so leaving any old broad one in place would silently defeat
    -- the firm-scoped policy we're about to add.
    FOR pol IN
      SELECT policyname FROM pg_policies
      WHERE schemaname='public' AND tablename=t
    LOOP
      EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', pol, t);
    END LOOP;

    EXECUTE format(
      'CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL AND %s)',
      t||'_read_authed', t, same_firm
    );
    EXECUTE format(
      'CREATE POLICY %I ON public.%I FOR INSERT TO authenticated WITH CHECK (auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(), ''viewer''::public.app_role) AND %s)',
      t||'_insert_staff', t, same_firm
    );
    EXECUTE format(
      'CREATE POLICY %I ON public.%I FOR UPDATE TO authenticated USING (auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(), ''viewer''::public.app_role) AND %s) WITH CHECK (auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(), ''viewer''::public.app_role) AND %s)',
      t||'_update_staff', t, same_firm, same_firm
    );
    EXECUTE format(
      'CREATE POLICY %I ON public.%I FOR DELETE TO authenticated USING (auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(), ''viewer''::public.app_role) AND %s)',
      t||'_delete_staff', t, same_firm
    );
  END LOOP;
END $$;


-- ------------------------------------------------------------------------------
-- [38/208] MIGRATION: 20260730170000_atomic_tenant_onboarding.sql
-- ------------------------------------------------------------------------------

-- Atomic tenant onboarding (Codex handover item 3) + default trial plan
-- (item 4 scaffolding). No fake firm/tenant is created here — only a
-- reusable plan-catalog row (configuration, not tenant data) and the
-- onboarding function itself. Calling it with a real firm's details is left
-- to whoever actually onboards the pilot tenant.
--
-- Atomicity: a PL/pgSQL function body runs inside the caller's transaction;
-- any RAISE EXCEPTION here rolls back every INSERT the function has made so
-- far, automatically — no partial organization/branch/profile/role/
-- subscription row can be left behind.

INSERT INTO public.platform_plans (code, name, description, billing_cycle, price_minor, feature_limits, is_active)
VALUES (
  'trial-6mo',
  'Six-Month Pilot Trial',
  'Default plan for the initial six-month customer pilot — no charge, full feature access unless a specific organization_features row overrides it.',
  'custom',
  0,
  '{}'::jsonb,
  true
)
ON CONFLICT (code) DO NOTHING;

CREATE OR REPLACE FUNCTION public.onboard_tenant(
  p_auth_id uuid,
  p_firm_name text,
  p_firm_slug text,
  p_owner_full_name text,
  p_branch_name text DEFAULT 'Main Branch',
  p_branch_code text DEFAULT 'MAIN',
  p_branch_address text DEFAULT '',
  p_branch_phone text DEFAULT '',
  p_plan_code text DEFAULT 'trial-6mo',
  p_trial_months integer DEFAULT 6
)
RETURNS TABLE (organization_id uuid, branch_id text, subscription_id uuid)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid;
  v_branch_id text;
  v_plan_id uuid;
  v_sub_id uuid;
BEGIN
  IF p_auth_id IS NULL THEN
    RAISE EXCEPTION 'onboard_tenant: p_auth_id is required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = p_auth_id) THEN
    RAISE EXCEPTION 'onboard_tenant: auth.users row % does not exist', p_auth_id;
  END IF;
  IF EXISTS (SELECT 1 FROM public.user_profiles WHERE auth_id = p_auth_id) THEN
    RAISE EXCEPTION 'onboard_tenant: user % already has a profile — onboarding is one-time per user', p_auth_id;
  END IF;
  IF trim(p_firm_name) = '' OR trim(p_firm_slug) = '' THEN
    RAISE EXCEPTION 'onboard_tenant: firm name and slug are required';
  END IF;

  SELECT id INTO v_plan_id FROM public.platform_plans WHERE code = p_plan_code AND is_active;
  IF v_plan_id IS NULL THEN
    RAISE EXCEPTION 'onboard_tenant: no active plan with code %', p_plan_code;
  END IF;

  INSERT INTO public.organizations (slug, name, license_type, is_active, data)
  VALUES (p_firm_slug, p_firm_name, 'trial', true, '{}'::jsonb)
  RETURNING id INTO v_org_id;

  v_branch_id := 'br_' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 12);
  INSERT INTO public.branches (id, firm_id, name, code, address, phone, manager_name, active, is_default, branch_type)
  VALUES (v_branch_id, v_org_id, p_branch_name, p_branch_code, p_branch_address, p_branch_phone, p_owner_full_name, true, true, 'main');

  INSERT INTO public.user_profiles (id, auth_id, firm_id, branch_id, full_name, status, active, is_super_owner, role, data, permissions)
  VALUES (gen_random_uuid(), p_auth_id, v_org_id, v_branch_id, p_owner_full_name, 'active', true, false, 'Owner', '{}'::jsonb, '{}'::jsonb);

  INSERT INTO public.user_roles (user_id, role)
  VALUES (p_auth_id, 'owner'::public.app_role)
  ON CONFLICT (user_id, role) DO NOTHING;

  INSERT INTO public.organization_subscriptions (organization_id, plan_id, status, trial_started_at, trial_ends_at)
  VALUES (v_org_id, v_plan_id, 'trial', now(), now() + make_interval(months => p_trial_months))
  RETURNING id INTO v_sub_id;

  INSERT INTO public.subscription_history (organization_id, subscription_id, action, after_value, actor_id, reason)
  VALUES (v_org_id, v_sub_id, 'trial_started', jsonb_build_object('plan_code', p_plan_code, 'trial_months', p_trial_months), p_auth_id, 'Initial tenant onboarding');

  RETURN QUERY SELECT v_org_id, v_branch_id, v_sub_id;
END;
$$;

REVOKE ALL ON FUNCTION public.onboard_tenant(uuid, text, text, text, text, text, text, text, text, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.onboard_tenant(uuid, text, text, text, text, text, text, text, text, integer) TO service_role;
-- Deliberately NOT granted to `authenticated` — onboarding a brand-new
-- tenant is a platform operation (run by whoever owns signup/admin
-- provisioning, via service_role), not something any logged-in user should
-- be able to call for themselves.


-- ------------------------------------------------------------------------------
-- [39/208] MIGRATION: 20260730180000_firm_scope_rls_wave2.sql
-- ------------------------------------------------------------------------------

-- P0 fix, wave 2: full-audit pass found 20 MORE tables with zero firm scoping
-- that weren't in the original 37-table advisor list (they use a different
-- single-ALL-policy shape — "<table>_authenticated_rw" — from a migration
-- that predates the firm-scoping work entirely, so the earlier advisor scan
-- and the first RLS-fix pass both missed them). Several are gold/financial-
-- adjacent: material_vault_movements (non-gold material vault ledger),
-- manufacturing_barcodes (finished-goods ownership/traceability),
-- financial_lock_periods (period-close gate), worker_returns,
-- outside_work_* (outside-jeweller gold ledger), polishing_transactions.
--
-- None of these 20 tables have a firm_id column at all (verified via
-- information_schema). Adding it nullable, then applying the exact same
-- safe-fallback firm-scoped policy pattern as
-- 20260730160000_firm_scope_rls_framework.sql. No lockout today (everything
-- still null both sides); real isolation the moment Codex's tenant
-- onboarding backfills firm_id.
--
-- branches/workshops handled separately below — they have their own
-- admin-gated write policies (is_admin()) that need to keep that gate while
-- adding firm scope, not the generic 4-policy shape.

ALTER TABLE public.approval_requests ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.credit_notes ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.customer_settlements ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.debit_notes ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.delivery_challans ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.estimates ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.financial_lock_periods ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.lot_batches ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.manufacturing_barcodes ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.material_vault_movements ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.module_states ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.order_issues ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.outside_work_labour_charges ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.outside_work_payments ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.outside_work_transactions ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.polishing_transactions ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.saved_filters ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.stone_details ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.worker_returns ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.workshops ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;

DO $$
DECLARE
  t text;
  pol text;
  tables text[] := ARRAY[
    'approval_requests','credit_notes','customer_settlements','debit_notes','delivery_challans',
    'estimates','financial_lock_periods','lot_batches','manufacturing_barcodes',
    'material_vault_movements','module_states','order_issues','outside_work_labour_charges',
    'outside_work_payments','outside_work_transactions','polishing_transactions','saved_filters',
    'stone_details','worker_returns'
  ];
  same_firm text := '(firm_id = public.my_firm_id() OR (firm_id IS NULL AND public.my_firm_id() IS NULL) OR public.has_role(auth.uid(), ''saas_admin''::public.app_role))';
BEGIN
  FOREACH t IN ARRAY tables LOOP
    FOR pol IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename=t LOOP
      EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', pol, t);
    END LOOP;
    EXECUTE format(
      'CREATE POLICY %I ON public.%I FOR ALL TO authenticated USING (auth.uid() IS NOT NULL AND %s) WITH CHECK (auth.uid() IS NOT NULL AND %s)',
      t||'_authenticated_rw', t, same_firm, same_firm
    );
  END LOOP;
END $$;

-- branches / workshops: keep the existing is_admin() write gate, add firm
-- scope to it and to the open "select true for any authenticated user" read
-- policy (both currently let any signed-in user, from any firm, read every
-- firm's branches/workshops).
DROP POLICY IF EXISTS branches_select ON public.branches;
CREATE POLICY branches_select ON public.branches FOR SELECT TO authenticated
  USING (firm_id = public.my_firm_id() OR (firm_id IS NULL AND public.my_firm_id() IS NULL) OR public.has_role(auth.uid(), 'saas_admin'::public.app_role));

DROP POLICY IF EXISTS branches_admin_insert ON public.branches;
CREATE POLICY branches_admin_insert ON public.branches FOR INSERT TO authenticated
  WITH CHECK (public.is_admin(auth.uid()) AND (firm_id = public.my_firm_id() OR (firm_id IS NULL AND public.my_firm_id() IS NULL)));

DROP POLICY IF EXISTS branches_admin_update ON public.branches;
CREATE POLICY branches_admin_update ON public.branches FOR UPDATE TO authenticated
  USING (public.is_admin(auth.uid()) AND (firm_id = public.my_firm_id() OR (firm_id IS NULL AND public.my_firm_id() IS NULL)))
  WITH CHECK (public.is_admin(auth.uid()) AND (firm_id = public.my_firm_id() OR (firm_id IS NULL AND public.my_firm_id() IS NULL)));

DROP POLICY IF EXISTS branches_admin_delete ON public.branches;
CREATE POLICY branches_admin_delete ON public.branches FOR DELETE TO authenticated
  USING (public.is_admin(auth.uid()) AND (firm_id = public.my_firm_id() OR (firm_id IS NULL AND public.my_firm_id() IS NULL)));

DROP POLICY IF EXISTS workshops_select ON public.workshops;
CREATE POLICY workshops_select ON public.workshops FOR SELECT TO authenticated
  USING (firm_id = public.my_firm_id() OR (firm_id IS NULL AND public.my_firm_id() IS NULL) OR public.has_role(auth.uid(), 'saas_admin'::public.app_role));

DROP POLICY IF EXISTS workshops_admin_insert ON public.workshops;
CREATE POLICY workshops_admin_insert ON public.workshops FOR INSERT TO authenticated
  WITH CHECK (public.is_admin(auth.uid()) AND (firm_id = public.my_firm_id() OR (firm_id IS NULL AND public.my_firm_id() IS NULL)));

DROP POLICY IF EXISTS workshops_admin_update ON public.workshops;
CREATE POLICY workshops_admin_update ON public.workshops FOR UPDATE TO authenticated
  USING (public.is_admin(auth.uid()) AND (firm_id = public.my_firm_id() OR (firm_id IS NULL AND public.my_firm_id() IS NULL)))
  WITH CHECK (public.is_admin(auth.uid()) AND (firm_id = public.my_firm_id() OR (firm_id IS NULL AND public.my_firm_id() IS NULL)));

