-- ------------------------------------------------------------------------------
-- [65/208] MIGRATION: 20260731200000_customer_portal_identity_and_rpc.sql
-- ------------------------------------------------------------------------------

-- Authenticated customer portal foundation.
-- A customer account must be explicitly linked to exactly one people row;
-- portal reads are returned by a SECURITY DEFINER function with tenant checks.
begin;

alter table public.user_profiles
  add column if not exists customer_person_id text references public.people(id) on delete set null;

create index if not exists idx_user_profiles_customer_person
  on public.user_profiles(customer_person_id)
  where customer_person_id is not null;

create or replace function public.get_customer_portal()
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_profile public.user_profiles;
  v_person public.people;
  v_firm uuid;
  v_result jsonb;
begin
  select * into v_profile
  from public.user_profiles
  where auth_id = auth.uid()
    and active
    and status = 'active'
    and lower(coalesce(role, '')) = 'customer'
  limit 1;

  if not found or v_profile.customer_person_id is null or v_profile.firm_id is null then
    raise exception 'customer portal access is not configured' using errcode = '42501';
  end if;

  v_firm := v_profile.firm_id;
  select * into v_person
  from public.people
  where id = v_profile.customer_person_id
    and firm_id = v_firm
    and type in ('customer', 'Customer')
    and active;

  if not found then
    raise exception 'customer profile was not found' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'profile', jsonb_build_object(
      'id', v_person.id,
      'full_name', v_person.full_name,
      'phone', v_person.phone,
      'whatsapp', v_person.whatsapp,
      'email', v_person.email,
      'village_city', v_person.village_city,
      'current_address', v_person.current_address
    ),
    'invoices', coalesce((select jsonb_agg(jsonb_build_object(
        'id', i.id, 'invoice_no', i.invoice_no, 'status', i.status,
        'gst', i.gst, 'subtotal_paise', i.subtotal_paise,
        'gst_paise', i.gst_paise, 'grand_total_paise', i.grand_total_paise,
        'paid_paise', i.paid_paise, 'balance_paise', i.balance_paise,
        'created_at', i.created_at
      ) order by i.created_at desc)
      from public.invoices i
      where i.firm_id = v_firm and i.customer_id = v_person.id), '[]'::jsonb),
    'orders', coalesce((select jsonb_agg(jsonb_build_object(
        'id', o.id, 'order_no', o.order_no, 'type', o.type,
        'status', o.status, 'expected_delivery', o.expected_delivery,
        'priority', o.priority, 'created_at', o.created_at
      ) order by o.created_at desc)
      from public.orders o
      where o.firm_id = v_firm and o.customer_id = v_person.id), '[]'::jsonb),
    'repairs', coalesce((select jsonb_agg(jsonb_build_object(
        'id', r.id, 'repair_no', r.repair_no, 'kind', r.kind,
        'status', r.status, 'estimated_charge_paise', r.estimated_charge_paise,
        'advance_paise', r.advance_paise, 'received_gross_mg', r.received_gross_mg,
        'created_at', r.created_at
      ) order by r.created_at desc)
      from public.repairs r
      where r.firm_id = v_firm and r.customer_id = v_person.id), '[]'::jsonb),
    'support_tickets', coalesce((select jsonb_agg(jsonb_build_object(
        'id', t.id, 'ticket_no', t.ticket_no, 'category', t.category,
        'subject', t.subject, 'description', t.description,
        'severity', t.severity, 'priority', t.priority, 'status', t.status,
        'resolution', case when t.status in ('resolved', 'closed') then t.resolution else null end,
        'created_at', t.created_at, 'updated_at', t.updated_at
      ) order by t.created_at desc)
      from public.platform_support_tickets t
      where t.firm_id = v_firm and t.requester_id = auth.uid()), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$$;

revoke all on function public.get_customer_portal() from public, anon;
grant execute on function public.get_customer_portal() to authenticated;

create or replace function public.create_customer_support_ticket(
  p_subject text,
  p_description text,
  p_category text default 'general',
  p_priority text default 'normal'
)
returns public.platform_support_tickets
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_profile public.user_profiles;
  v_ticket public.platform_support_tickets;
  v_priority text := lower(trim(coalesce(p_priority, 'normal')));
begin
  if length(trim(coalesce(p_subject, ''))) < 3 or length(trim(coalesce(p_subject, ''))) > 160 then
    raise exception 'subject must be between 3 and 160 characters' using errcode = '22023';
  end if;
  if length(trim(coalesce(p_description, ''))) < 10 or length(trim(coalesce(p_description, ''))) > 10000 then
    raise exception 'description must be between 10 and 10000 characters' using errcode = '22023';
  end if;
  if v_priority not in ('low', 'normal', 'high', 'urgent') then
    raise exception 'invalid priority' using errcode = '22023';
  end if;

  select * into v_profile from public.user_profiles
  where auth_id = auth.uid() and active and status = 'active'
    and lower(coalesce(role, '')) = 'customer' and firm_id is not null
  limit 1;
  if not found then
    raise exception 'customer portal access is not configured' using errcode = '42501';
  end if;

  insert into public.platform_support_tickets
    (ticket_no, firm_id, branch_id, requester_id, category, subject, description, priority)
  values
    ('CUS-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS') || '-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6)),
     v_profile.firm_id, v_profile.branch_id, auth.uid(),
     left(trim(coalesce(p_category, 'general')), 80), trim(p_subject), trim(p_description), v_priority)
  returning * into v_ticket;

  return v_ticket;
end;
$$;

revoke all on function public.create_customer_support_ticket(text, text, text, text) from public, anon;
grant execute on function public.create_customer_support_ticket(text, text, text, text) to authenticated;

commit;


-- ------------------------------------------------------------------------------
-- [66/208] MIGRATION: 20260731210000_customer_support_conversations.sql
-- ------------------------------------------------------------------------------

-- Customer-visible support threads. Messages are always tenant- and requester-scoped.
alter table public.platform_conversation_messages
  drop constraint if exists platform_conversation_messages_body_check;
alter table public.platform_conversation_messages
  add constraint platform_conversation_messages_body_check
  check (length(trim(body)) between 1 and 10000);

create or replace function public.ensure_support_ticket_conversation()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.platform_conversations (firm_id, ticket_id, status)
  values (new.firm_id, new.id, 'open')
  on conflict do nothing;
  return new;
end;
$$;

drop trigger if exists platform_support_ticket_conversation on public.platform_support_tickets;
create trigger platform_support_ticket_conversation
after insert on public.platform_support_tickets
for each row execute function public.ensure_support_ticket_conversation();

create or replace function public.get_customer_support_thread(p_ticket_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_result jsonb;
begin
  select jsonb_build_object(
    'ticket', jsonb_build_object(
      'id', t.id, 'ticket_no', t.ticket_no, 'subject', t.subject,
      'status', t.status, 'priority', t.priority, 'created_at', t.created_at,
      'updated_at', t.updated_at
    ),
    'messages', coalesce((select jsonb_agg(jsonb_build_object(
      'id', m.id, 'body', m.body, 'status', m.status, 'created_at', m.created_at,
      'sender', case when m.sender_id = auth.uid() then 'customer' else 'support' end
    ) order by m.created_at)
      from public.platform_conversation_messages m
      where m.conversation_id = c.id and m.visibility = 'customer'), '[]'::jsonb)
  ) into v_result
  from public.platform_support_tickets t
  join public.platform_conversations c on c.ticket_id = t.id
  where t.id = p_ticket_id
    and t.firm_id = public.my_firm_id()
    and t.requester_id = auth.uid();

  if v_result is null then
    raise exception 'Support ticket not found';
  end if;
  return v_result;
end;
$$;

create or replace function public.reply_customer_support_ticket(
  p_ticket_id uuid,
  p_body text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_conversation public.platform_conversations;
  v_message public.platform_conversation_messages;
begin
  if length(trim(coalesce(p_body, ''))) not between 1 and 10000 then
    raise exception 'Message must contain between 1 and 10000 characters';
  end if;

  select c.* into v_conversation
  from public.platform_conversations c
  join public.platform_support_tickets t on t.id = c.ticket_id
  where c.ticket_id = p_ticket_id
    and t.firm_id = public.my_firm_id()
    and t.requester_id = auth.uid();

  if v_conversation.id is null then
    raise exception 'Support ticket not found';
  end if;
  if v_conversation.status = 'closed' then
    raise exception 'Closed support tickets cannot receive replies';
  end if;

  insert into public.platform_conversation_messages (conversation_id, sender_id, body, visibility)
  values (v_conversation.id, auth.uid(), trim(p_body), 'customer')
  returning * into v_message;

  update public.platform_conversations
  set status = 'waiting', updated_at = now()
  where id = v_conversation.id;
  update public.platform_support_tickets
  set status = case when status in ('resolved', 'closed') then 'reopened' else status end,
      updated_at = now()
  where id = p_ticket_id;

  return jsonb_build_object(
    'id', v_message.id, 'body', v_message.body,
    'status', v_message.status, 'created_at', v_message.created_at, 'sender', 'customer'
  );
end;
$$;

revoke all on function public.get_customer_support_thread(uuid) from public, anon;
revoke all on function public.reply_customer_support_ticket(uuid, text) from public, anon;
grant execute on function public.get_customer_support_thread(uuid) to authenticated;
grant execute on function public.reply_customer_support_ticket(uuid, text) to authenticated;

create policy platform_conversations_customer_read on public.platform_conversations
for select to authenticated
using (
  exists (
    select 1 from public.platform_support_tickets t
    where t.id = ticket_id and t.firm_id = public.my_firm_id() and t.requester_id = auth.uid()
  )
);

create policy platform_messages_customer_read on public.platform_conversation_messages
for select to authenticated
using (
  visibility = 'customer' and exists (
    select 1 from public.platform_conversations c
    join public.platform_support_tickets t on t.id = c.ticket_id
    where c.id = conversation_id and t.firm_id = public.my_firm_id() and t.requester_id = auth.uid()
  )
);

create policy platform_messages_customer_insert on public.platform_conversation_messages
for insert to authenticated
with check (
  sender_id = auth.uid() and visibility = 'customer' and exists (
    select 1 from public.platform_conversations c
    join public.platform_support_tickets t on t.id = c.ticket_id
    where c.id = conversation_id and t.firm_id = public.my_firm_id() and t.requester_id = auth.uid()
  )
);


-- ------------------------------------------------------------------------------
-- [67/208] MIGRATION: 20260731220000_platform_ticket_transition_rpc.sql
-- ------------------------------------------------------------------------------

-- Platform support status changes are validated and audited server-side.
create or replace function public.transition_platform_support_ticket(
  p_ticket_id uuid,
  p_status text
)
returns public.platform_support_tickets
language plpgsql
security definer
set search_path = public
as $$
declare
  v_ticket public.platform_support_tickets;
  v_previous_status text;
  v_allowed boolean := false;
begin
  if not public.is_saas_admin() then
    raise exception 'Platform administrator access required';
  end if;
  if p_status not in ('open','acknowledged','in_progress','waiting_customer','resolved','closed','reopened') then
    raise exception 'Invalid support ticket status';
  end if;

  select * into v_ticket from public.platform_support_tickets where id = p_ticket_id for update;
  if v_ticket.id is null then raise exception 'Support ticket not found'; end if;
  v_previous_status := v_ticket.status;
  v_allowed :=
    (v_ticket.status = p_status) or
    (v_ticket.status = 'open' and p_status = 'acknowledged') or
    (v_ticket.status = 'acknowledged' and p_status in ('in_progress','waiting_customer')) or
    (v_ticket.status = 'in_progress' and p_status in ('waiting_customer','resolved')) or
    (v_ticket.status = 'waiting_customer' and p_status in ('in_progress','resolved')) or
    (v_ticket.status = 'resolved' and p_status in ('closed','reopened')) or
    (v_ticket.status = 'reopened' and p_status in ('acknowledged','in_progress'));
  if not v_allowed then
    raise exception 'Invalid support ticket transition from % to %', v_ticket.status, p_status;
  end if;

  update public.platform_support_tickets
  set status = p_status,
      resolved_at = case when p_status = 'resolved' then coalesce(resolved_at, now()) when p_status = 'reopened' then null else resolved_at end,
      closed_at = case when p_status = 'closed' then coalesce(closed_at, now()) when p_status = 'reopened' then null else closed_at end,
      updated_at = now()
  where id = p_ticket_id
  returning * into v_ticket;

  insert into public.platform_audit_events
    (actor_id, action, organization_id, target_type, target_id, reason, before_value, after_value)
  values
    (auth.uid(), 'support_ticket.status_changed', v_ticket.firm_id, 'support_ticket', v_ticket.id,
     'Status transition through platform control center',
     jsonb_build_object('status', v_previous_status),
     jsonb_build_object('status', p_status));
  return v_ticket;
end;
$$;

revoke all on function public.transition_platform_support_ticket(uuid, text) from public, anon;
grant execute on function public.transition_platform_support_ticket(uuid, text) to authenticated;


