-- ------------------------------------------------------------------------------
-- [91/208] MIGRATION: 20260801133257_fix_app_settings_multi_tenant.sql
-- ------------------------------------------------------------------------------

-- Reconciled from production (project dqgrrafuoxaorvyrcuuh) on 2026-08-11 — this migration was applied directly to Supabase and had no local file until now.

-- Multi-tenant app_settings: global singleton ids (firm, comm_configs) conflicted with
-- firm-scoped RLS after 20260730160000. Staff tenants could not upsert settings → 403
-- toast storm ("could not complete a database operation") on every persist/click.

begin;

-- Firm settings: one row per tenant keyed by organization id (text).
update public.app_settings
set id = firm_id::text
where id = 'firm'
  and firm_id is not null
  and id <> firm_id::text;

insert into public.app_settings (id, firm_id, scope, data)
select o.id::text, o.id, 'firm', '{}'::jsonb
from public.organizations o
where not exists (
  select 1 from public.app_settings a
  where a.firm_id = o.id and a.scope = 'firm'
);

-- Communication provider configs: clone legacy global row per tenant when missing.
insert into public.app_settings (id, firm_id, scope, data)
select o.id::text || ':comm_configs', o.id, 'firm', g.data
from public.organizations o
join public.app_settings g on g.id = 'comm_configs' and g.firm_id is null
where not exists (
  select 1 from public.app_settings a where a.id = o.id::text || ':comm_configs'
);

-- Business rules blob (if present): same per-tenant pattern.
insert into public.app_settings (id, firm_id, scope, data)
select o.id::text || ':business_rules', o.id, 'firm', g.data
from public.organizations o
join public.app_settings g on g.id = 'business_rules' and g.firm_id is null
where not exists (
  select 1 from public.app_settings a where a.id = o.id::text || ':business_rules'
);

-- Legacy global rows are superseded; tenants now have firm-scoped copies.
delete from public.app_settings
where firm_id is null
  and id in ('comm_configs', 'business_rules');

commit;


-- ------------------------------------------------------------------------------
-- [92/208] MIGRATION: 20260801134237_firm_customer_support_tickets.sql
-- ------------------------------------------------------------------------------

-- Reconciled from production (project dqgrrafuoxaorvyrcuuh) on 2026-08-11 — this migration was applied directly to Supabase and had no local file until now.

-- Company-tenant staff can manage customer portal support tickets (CUS-* queue).

begin;

create or replace function public.is_firm_ticket_staff()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.is_saas_admin()
    or exists (
      select 1
      from public.user_profiles up
      where up.auth_id = auth.uid()
        and up.active
        and up.status = 'active'
        and up.firm_id is not null
        and lower(coalesce(up.role, '')) not in ('customer', 'viewer')
    );
$$;

revoke all on function public.is_firm_ticket_staff() from public, anon;
grant execute on function public.is_firm_ticket_staff() to authenticated;

create or replace function public.list_customer_portal_support_tickets(
  p_status text default null,
  p_priority text default null
)
returns setof public.platform_support_tickets
language plpgsql
security definer
set search_path = public
as $$
declare
  v_firm uuid := public.my_firm_id();
begin
  if v_firm is null or not public.is_firm_ticket_staff() then
    raise exception 'firm ticket access is not configured' using errcode = '42501';
  end if;

  return query
  select t.*
  from public.platform_support_tickets t
  where t.firm_id = v_firm
    and t.ticket_no like 'CUS-%'
    and (p_status is null or t.status = lower(trim(p_status)))
    and (p_priority is null or t.priority = lower(trim(p_priority)))
  order by t.created_at desc
  limit 200;
end;
$$;

create or replace function public.get_firm_customer_support_thread(p_ticket_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_result jsonb;
begin
  if not public.is_firm_ticket_staff() then
    raise exception 'firm ticket access is not configured' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'ticket', jsonb_build_object(
      'id', t.id,
      'ticket_no', t.ticket_no,
      'subject', t.subject,
      'description', t.description,
      'status', t.status,
      'priority', t.priority,
      'category', t.category,
      'requester_id', t.requester_id,
      'assigned_to', t.assigned_to,
      'created_at', t.created_at,
      'updated_at', t.updated_at,
      'sla_due_at', t.sla_due_at
    ),
    'messages', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', m.id,
            'body', m.body,
            'created_at', m.created_at,
            'sender', case when m.sender_id = t.requester_id then 'customer' else 'support' end
          )
          order by m.created_at
        )
        from public.platform_conversation_messages m
        where m.conversation_id = c.id
          and m.visibility = 'customer'
      ),
      '[]'::jsonb
    )
  ) into v_result
  from public.platform_support_tickets t
  join public.platform_conversations c on c.ticket_id = t.id
  where t.id = p_ticket_id
    and t.firm_id = public.my_firm_id()
    and t.ticket_no like 'CUS-%';

  if v_result is null then
    raise exception 'Support ticket not found';
  end if;
  return v_result;
end;
$$;

create or replace function public.reply_firm_customer_support_ticket(
  p_ticket_id uuid,
  p_body text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_ticket public.platform_support_tickets;
  v_conversation public.platform_conversations;
  v_message public.platform_conversation_messages;
begin
  if not public.is_firm_ticket_staff() then
    raise exception 'firm ticket access is not configured' using errcode = '42501';
  end if;
  if length(trim(coalesce(p_body, ''))) not between 1 and 10000 then
    raise exception 'Message must contain between 1 and 10000 characters';
  end if;

  select * into v_ticket
  from public.platform_support_tickets t
  where t.id = p_ticket_id
    and t.firm_id = public.my_firm_id()
    and t.ticket_no like 'CUS-%';

  if v_ticket.id is null then
    raise exception 'Support ticket not found';
  end if;

  select * into v_conversation
  from public.platform_conversations c
  where c.ticket_id = p_ticket_id;

  if v_conversation.status = 'closed' then
    raise exception 'Closed support tickets cannot receive replies';
  end if;

  insert into public.platform_conversation_messages (conversation_id, sender_id, body, visibility)
  values (v_conversation.id, auth.uid(), trim(p_body), 'customer')
  returning * into v_message;

  update public.platform_conversations
  set status = 'open',
      assigned_to = coalesce(v_conversation.assigned_to, auth.uid()),
      updated_at = now()
  where id = v_conversation.id;

  update public.platform_support_tickets
  set status = case when status in ('resolved', 'closed') then 'reopened' else 'in_progress' end,
      assigned_to = coalesce(assigned_to, auth.uid()),
      updated_at = now()
  where id = p_ticket_id;

  return jsonb_build_object(
    'id', v_message.id,
    'body', v_message.body,
    'created_at', v_message.created_at,
    'sender', 'support'
  );
end;
$$;

create or replace function public.transition_firm_customer_support_ticket(
  p_ticket_id uuid,
  p_status text
)
returns public.platform_support_tickets
language plpgsql
security definer
set search_path = public
as $$
declare
  v_status text := lower(trim(coalesce(p_status, '')));
  v_ticket public.platform_support_tickets;
begin
  if not public.is_firm_ticket_staff() then
    raise exception 'firm ticket access is not configured' using errcode = '42501';
  end if;
  if v_status not in ('open', 'in_progress', 'waiting_customer', 'resolved', 'closed', 'reopened') then
    raise exception 'invalid ticket status' using errcode = '22023';
  end if;

  update public.platform_support_tickets t
  set status = v_status,
      resolved_at = case when v_status = 'resolved' then now() else t.resolved_at end,
      closed_at = case when v_status = 'closed' then now() else t.closed_at end,
      updated_at = now()
  where t.id = p_ticket_id
    and t.firm_id = public.my_firm_id()
    and t.ticket_no like 'CUS-%'
  returning * into v_ticket;

  if v_ticket.id is null then
    raise exception 'Support ticket not found';
  end if;

  update public.platform_conversations c
  set status = case when v_status = 'closed' then 'closed' else c.status end,
      updated_at = now()
  where c.ticket_id = p_ticket_id;

  return v_ticket;
end;
$$;

revoke all on function public.list_customer_portal_support_tickets(text, text) from public, anon;
revoke all on function public.get_firm_customer_support_thread(uuid) from public, anon;
revoke all on function public.reply_firm_customer_support_ticket(uuid, text) from public, anon;
revoke all on function public.transition_firm_customer_support_ticket(uuid, text) from public, anon;

grant execute on function public.list_customer_portal_support_tickets(text, text) to authenticated;
grant execute on function public.get_firm_customer_support_thread(uuid) to authenticated;
grant execute on function public.reply_firm_customer_support_ticket(uuid, text) to authenticated;
grant execute on function public.transition_firm_customer_support_ticket(uuid, text) to authenticated;

commit;


-- ------------------------------------------------------------------------------
-- [93/208] MIGRATION: 20260801151602_support_ticket_notifications.sql
-- ------------------------------------------------------------------------------

-- Reconciled from production (project dqgrrafuoxaorvyrcuuh) on 2026-08-11 — this migration was applied directly to Supabase and had no local file until now.

-- Notify platform admins and firm staff when support tickets are created.

begin;

create or replace function public.notify_support_ticket_created()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_recipient uuid;
  v_platform_href text := '/platform?view=tickets';
  v_firm_href text := '/communications/customer-tickets';
begin
  for v_recipient in
    select ur.user_id
    from public.user_roles ur
    where ur.role = 'saas_admin'::public.app_role
  loop
    insert into public.platform_notifications (recipient_id, firm_id, kind, title, body, href)
    values (
      v_recipient,
      new.firm_id,
      'support_ticket',
      'New support ticket',
      new.ticket_no || ' · ' || left(trim(new.subject), 120),
      v_platform_href
    );
  end loop;

  if new.ticket_no like 'CUS-%' and new.firm_id is not null then
    for v_recipient in
      select up.auth_id
      from public.user_profiles up
      where up.firm_id = new.firm_id
        and up.active
        and up.status = 'active'
        and up.auth_id is not null
        and lower(coalesce(up.role, '')) in (
          'owner',
          'admin',
          'administrator',
          'super owner',
          'branch manager',
          'ceo'
        )
    loop
      insert into public.platform_notifications (recipient_id, firm_id, kind, title, body, href)
      values (
        v_recipient,
        new.firm_id,
        'customer_support_ticket',
        'Customer support ticket',
        new.ticket_no || ' · ' || left(trim(new.subject), 120),
        v_firm_href
      );
    end loop;
  end if;

  return new;
end;
$$;

drop trigger if exists platform_support_ticket_notify on public.platform_support_tickets;
create trigger platform_support_ticket_notify
after insert on public.platform_support_tickets
for each row
execute function public.notify_support_ticket_created();

create or replace function public.create_customer_support_ticket(
  p_subject text,
  p_description text,
  p_category text default 'general',
  p_priority text default 'normal'
)
returns public.platform_support_tickets
language plpgsql
security definer
set search_path = public
as $$
declare
  v_profile public.user_profiles;
  v_ticket public.platform_support_tickets;
  v_conversation_id uuid;
  v_priority text := lower(trim(coalesce(p_priority, 'normal')));
begin
  if length(trim(coalesce(p_subject, ''))) < 3 or length(trim(coalesce(p_subject, ''))) > 160 then
    raise exception 'subject must be between 3 and 160 characters' using errcode = '22023';
  end if;
  if length(trim(coalesce(p_description, ''))) < 10 or length(trim(coalesce(p_description, ''))) > 10000 then
    raise exception 'description must be between 10 and 10000 characters' using errcode = '22023';
  end if;
  if v_priority not in ('low', 'normal', 'high', 'urgent') then
    raise exception 'invalid priority' using errcode = '22023';
  end if;

  select * into v_profile
  from public.user_profiles
  where auth_id = auth.uid()
    and active
    and status = 'active'
    and lower(coalesce(role, '')) = 'customer'
    and firm_id is not null
  limit 1;

  if not found then
    raise exception 'customer portal access is not configured' using errcode = '42501';
  end if;

  insert into public.platform_support_tickets
    (ticket_no, firm_id, branch_id, requester_id, category, subject, description, priority)
  values
    (
      'CUS-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS') || '-' ||
        upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6)),
      v_profile.firm_id,
      v_profile.branch_id,
      auth.uid(),
      left(trim(coalesce(p_category, 'general')), 80),
      trim(p_subject),
      trim(p_description),
      v_priority
    )
  returning * into v_ticket;

  select c.id into v_conversation_id
  from public.platform_conversations c
  where c.ticket_id = v_ticket.id;

  if v_conversation_id is not null then
    insert into public.platform_conversation_messages (conversation_id, sender_id, body, visibility)
    values (v_conversation_id, auth.uid(), trim(p_description), 'customer');
  end if;

  return v_ticket;
end;
$$;

commit;


-- ------------------------------------------------------------------------------
-- [94/208] MIGRATION: 20260801162047_billing_branch_isolation_hardening.sql
-- ------------------------------------------------------------------------------

-- Reconciled from production (project dqgrrafuoxaorvyrcuuh) on 2026-08-11 — this migration was applied directly to Supabase and had no local file until now.

begin;

update public.invoices i
set
  customer_id = coalesce(i.customer_id, i.data->>'customerId'),
  firm_id = coalesce(i.firm_id, (i.data->>'firmId')::uuid)
where i.customer_id is null
   or i.firm_id is null;

update public.invoices i
set firm_id = b.firm_id
from public.branches b
where i.firm_id is null
  and coalesce(i.data->>'branchId', '') = b.id
  and b.firm_id is not null;

update public.branches b
set firm_id = up.firm_id
from public.user_profiles up
where b.firm_id is null
  and up.branch_id = b.id
  and up.firm_id is not null;

create or replace function public.is_customer_role()
returns boolean
language sql
stable
security definer
set search_path = pg_catalog, public
as $$
  select exists (
    select 1
    from public.user_profiles up
    where up.auth_id = auth.uid()
      and up.active
      and up.status = 'active'
      and (
        lower(coalesce(up.role, '')) = 'customer'
        or (
          up.customer_person_id is not null
          and lower(coalesce(up.role, '')) in ('viewer', 'customer portal', 'customer_portal')
        )
      )
  );
$$;

create or replace function public.my_customer_person_id()
returns text
language sql
stable
security definer
set search_path = pg_catalog, public
as $$
  select up.customer_person_id
  from public.user_profiles up
  where up.auth_id = auth.uid()
    and up.active
    and up.status = 'active'
    and up.customer_person_id is not null
    and (
      lower(coalesce(up.role, '')) = 'customer'
      or lower(coalesce(up.role, '')) in ('viewer', 'customer portal', 'customer_portal')
    )
  limit 1;
$$;

drop policy if exists invoices_read_authed on public.invoices;

create policy invoices_firm_read on public.invoices
  for select to authenticated
  using (
    public.is_saas_admin()
    or firm_id = public.my_firm_id()
  );

drop policy if exists branches_select on public.branches;

create policy branches_select on public.branches
  for select to authenticated
  using (
    public.is_saas_admin()
    or (
      public.my_firm_id() is not null
      and firm_id = public.my_firm_id()
    )
  );

commit;


-- ------------------------------------------------------------------------------
-- [95/208] MIGRATION: 20260801191441_specialist_payment_clearance.sql
-- ------------------------------------------------------------------------------

-- Reconciled from production (project dqgrrafuoxaorvyrcuuh) on 2026-08-11 — this migration was applied directly to Supabase and had no local file until now.

-- Specialist worker payment clearance (polish, meena, stone setting).
-- Variance accrues per completed job; cleared weekly/monthly from Attendance.

CREATE TABLE IF NOT EXISTS public.specialist_work_variances (
  id TEXT PRIMARY KEY,
  firm_id UUID NOT NULL DEFAULT public.my_firm_id() REFERENCES public.organizations(id) ON DELETE CASCADE,
  branch_id TEXT REFERENCES public.branches(id) ON DELETE SET NULL,
  data JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.specialist_payment_clearances (
  id TEXT PRIMARY KEY,
  firm_id UUID NOT NULL DEFAULT public.my_firm_id() REFERENCES public.organizations(id) ON DELETE CASCADE,
  branch_id TEXT REFERENCES public.branches(id) ON DELETE SET NULL,
  data JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

GRANT SELECT, INSERT, UPDATE, DELETE ON public.specialist_work_variances TO authenticated;
GRANT ALL ON public.specialist_work_variances TO service_role;
ALTER TABLE public.specialist_work_variances ENABLE ROW LEVEL SECURITY;

GRANT SELECT, INSERT, UPDATE, DELETE ON public.specialist_payment_clearances TO authenticated;
GRANT ALL ON public.specialist_payment_clearances TO service_role;
ALTER TABLE public.specialist_payment_clearances ENABLE ROW LEVEL SECURITY;

DO $$
DECLARE
  t text;
  pol text;
  tables text[] := ARRAY['specialist_work_variances', 'specialist_payment_clearances'];
BEGIN
  FOREACH t IN ARRAY tables LOOP
    FOR pol IN
      SELECT policyname FROM pg_policies
      WHERE schemaname = 'public' AND tablename = t
    LOOP
      EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', pol, t);
    END LOOP;

    EXECUTE format(
      'CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (firm_id = public.my_firm_id() OR public.has_role(auth.uid(), ''saas_admin''::public.app_role))',
      t || '_read_authed', t
    );
    EXECUTE format(
      'CREATE POLICY %I ON public.%I FOR INSERT TO authenticated WITH CHECK (firm_id = public.my_firm_id() AND NOT public.has_role(auth.uid(), ''viewer''::public.app_role))',
      t || '_insert_staff', t
    );
    EXECUTE format(
      'CREATE POLICY %I ON public.%I FOR UPDATE TO authenticated USING ((firm_id = public.my_firm_id() OR public.has_role(auth.uid(), ''saas_admin''::public.app_role)) AND NOT public.has_role(auth.uid(), ''viewer''::public.app_role)) WITH CHECK (firm_id = public.my_firm_id() AND NOT public.has_role(auth.uid(), ''viewer''::public.app_role))',
      t || '_update_staff', t
    );
  END LOOP;
END $$;


-- ------------------------------------------------------------------------------
-- [96/208] MIGRATION: 20260802101041_atomic_gold_ledger_rpc.sql
-- ------------------------------------------------------------------------------

-- Reconciled from production (project dqgrrafuoxaorvyrcuuh) on 2026-08-11 — this migration was applied directly to Supabase and had no local file until now.

-- Atomic gold ledger posting for conversion, deposit, and workshop flows.
-- Client posts multiple entries in one transaction; vault balance validated server-side.

create or replace function public.post_gold_ledger_entries(p_entries jsonb)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_firm uuid;
  v_entry jsonb;
  v_vault_delta bigint;
  v_vault_before bigint;
  v_id text;
  v_ts timestamptz;
  v_result jsonb := '[]'::jsonb;
begin
  if p_entries is null or jsonb_typeof(p_entries) <> 'array' or jsonb_array_length(p_entries) = 0 then
    raise exception 'p_entries must be a non-empty JSON array' using errcode = '22023';
  end if;

  v_firm := public.my_firm_id();
  if v_firm is null and not public.has_role(auth.uid(), 'saas_admin'::public.app_role) then
    raise exception 'firm context required for gold ledger posting' using errcode = '42501';
  end if;

  -- Sum vault deltas in this batch
  v_vault_delta := 0;
  for v_entry in select * from jsonb_array_elements(p_entries)
  loop
    v_vault_delta := v_vault_delta + coalesce((v_entry->'deltas'->>'vault')::bigint, 0);
  end loop;

  if v_vault_delta < 0 then
    select coalesce(sum((bucket_deltas->>'vault')::bigint), 0)
    into v_vault_before
    from public.gold_ledger
    where firm_id = v_firm or (firm_id is null and v_firm is null);

    if v_vault_before + v_vault_delta < 0 then
      raise exception 'Gold Vault balance cannot become negative' using errcode = '23514';
    end if;
  end if;

  for v_entry in select * from jsonb_array_elements(p_entries)
  loop
    v_id := coalesce(v_entry->>'id', gen_random_uuid()::text);
    v_ts := coalesce(
      to_timestamp((v_entry->>'createdAt')::double precision / 1000.0),
      now()
    );

    insert into public.gold_ledger (
      id, ts, movement, net_fine_mg, bucket_deltas, reference, note, data, firm_id
    ) values (
      v_id,
      v_ts,
      v_entry->>'type',
      (v_entry->>'netFineMg')::bigint,
      v_entry->'deltas',
      nullif(v_entry->>'reference', ''),
      nullif(v_entry->>'notes', ''),
      v_entry,
      v_firm
    )
    on conflict (id) do update set
      ts = excluded.ts,
      movement = excluded.movement,
      net_fine_mg = excluded.net_fine_mg,
      bucket_deltas = excluded.bucket_deltas,
      reference = excluded.reference,
      note = excluded.note,
      data = excluded.data,
      firm_id = excluded.firm_id;

    v_result := v_result || jsonb_build_array(v_entry || jsonb_build_object('id', v_id));
  end loop;

  return v_result;
end;
$$;

revoke all on function public.post_gold_ledger_entries(jsonb) from public, anon;
grant execute on function public.post_gold_ledger_entries(jsonb) to authenticated;


-- ------------------------------------------------------------------------------
-- [97/208] MIGRATION: 20260802101054_firm_id_backfill_single_tenant_v2.sql
-- ------------------------------------------------------------------------------

-- Reconciled from production (project dqgrrafuoxaorvyrcuuh) on 2026-08-11 — this migration was applied directly to Supabase and had no local file until now.

do $$
declare
  v_org uuid;
  v_count int;
  t text;
  tables text[] := array[
    'gold_ledger','invoices','orders','people','payments','inventory','job_cards',
    'gold_settlements','metal_conversions','customer_gold_deposits','material_vault_movements',
    'manufacturing_bills','melt_jobs','repairs','app_settings','worker_transactions'
  ];
begin
  select count(*), (array_agg(id order by created_at nulls last))[1]
  into v_count, v_org
  from public.organizations;
  if v_count <> 1 or v_org is null then
    raise notice 'firm_id backfill skipped: % organizations (need exactly 1)', v_count;
    return;
  end if;

  foreach t in array tables loop
    if to_regclass('public.' || t) is null then
      continue;
    end if;
    if not exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = t and column_name = 'firm_id'
    ) then
      continue;
    end if;
    execute format(
      'update public.%I set firm_id = $1 where firm_id is null',
      t
    ) using v_org;
  end loop;

  update public.user_profiles set firm_id = v_org where firm_id is null;
  update public.branches set firm_id = v_org where firm_id is null;
end;
$$;


