create or replace function public.onboard_tenant(p_auth_id uuid, p_firm_name text, p_firm_slug text, p_owner_full_name text, p_branch_name text default 'Main Branch', p_branch_code text default 'MAIN', p_branch_address text default '', p_branch_phone text default '', p_plan_code text default 'trial-6mo', p_trial_months integer default 6) returns table (organization_id uuid, branch_id text, subscription_id uuid) language plpgsql security definer set search_path = public as $$ declare v_org_id uuid; v_branch_id text; v_plan_id uuid; v_sub_id uuid; begin if p_auth_id is null then raise exception 'onboard_tenant: p_auth_id is required'; end if; if not exists (select 1 from auth.users where id = p_auth_id) then raise exception 'onboard_tenant: auth.users row % does not exist', p_auth_id; end if; if exists (select 1 from public.user_profiles where auth_id = p_auth_id) then raise exception 'onboard_tenant: user % already has a profile', p_auth_id; end if; if trim(p_firm_name) = '' or trim(p_firm_slug) = '' then raise exception 'onboard_tenant: firm name and slug are required'; end if; select id into v_plan_id from public.platform_plans where code = p_plan_code and is_active; if v_plan_id is null then raise exception 'onboard_tenant: no active plan with code %', p_plan_code; end if; insert into public.organizations (slug, name, license_type, is_active, data) values (p_firm_slug, p_firm_name, 'trial', true, '{}'::jsonb) returning id into v_org_id; v_branch_id := 'br_' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 12); insert into public.branches (id, firm_id, name, code, address, phone, manager_name, active, is_default, branch_type) values (v_branch_id, v_org_id, p_branch_name, p_branch_code, p_branch_address, p_branch_phone, p_owner_full_name, true, true, 'main'); insert into public.user_profiles (id, auth_id, firm_id, branch_id, full_name, status, active, is_super_owner, role, data, permissions) values (gen_random_uuid(), p_auth_id, v_org_id, v_branch_id, p_owner_full_name, 'active', true, false, 'Owner', '{}'::jsonb, '{}'::jsonb); insert into public.user_roles (user_id, role) values (p_auth_id, 'owner'::public.app_role) on conflict (user_id, role) do nothing; insert into public.organization_subscriptions (organization_id, plan_id, status, trial_started_at, trial_ends_at) values (v_org_id, v_plan_id, 'trial', now(), now() + make_interval(months => p_trial_months)) returning id into v_sub_id; perform public.apply_plan_entitlements(v_org_id, v_plan_id, 'Initial tenant onboarding'); insert into public.subscription_history (organization_id, subscription_id, action, after_value, actor_id, reason) values (v_org_id, v_sub_id, 'trial_started', jsonb_build_object('plan_code', p_plan_code, 'trial_months', p_trial_months), p_auth_id, 'Initial tenant onboarding'); return query select v_org_id, v_branch_id, v_sub_id; end; $$; create or replace function public.export_entitlement_enabled() returns boolean language sql stable security definer set search_path = public as $$ select public.organization_feature_enabled('export'); $$; revoke all on function public.export_entitlement_enabled() from public, anon; grant execute on function public.export_entitlement_enabled() to authenticated, service_role;


-- ------------------------------------------------------------------------------
-- [118/208] MIGRATION: 20260811060000_create_audit_log_table.sql
-- ------------------------------------------------------------------------------

-- Audit log moves from per-device local sql.js storage to shared Supabase
-- storage — the app is online-only now, there is no local database. The
-- hash-chain (prev_hash/hash) still gives global tamper-evidence across every
-- device once seq is a single shared sequence. The HMAC signature stays
-- device-local (signed with a key that never leaves the writing device), so
-- verification of the signature itself is still scoped to the current
-- device's own entries — the app-side verifyAuditChain() only asserts
-- signature validity for entries whose device_id matches the verifying
-- device, and relies on the hash chain for cross-device tamper-evidence.
CREATE TABLE IF NOT EXISTS public.audit_log (
  seq bigserial PRIMARY KEY,
  id text UNIQUE NOT NULL,
  ts timestamptz NOT NULL DEFAULT now(),
  actor_id uuid,
  actor_email text,
  action text NOT NULL,
  entity_type text NOT NULL,
  entity_id text,
  before_json text,
  after_json text,
  device_id text,
  prev_hash text NOT NULL,
  hash text NOT NULL,
  signature text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS audit_log_entity_idx ON public.audit_log (entity_type, entity_id);
CREATE INDEX IF NOT EXISTS audit_log_actor_idx ON public.audit_log (actor_id);

ALTER TABLE public.audit_log ENABLE ROW LEVEL SECURITY;

-- Append-only from the app's perspective: authenticated users can insert and
-- read, nobody can update/delete (that would defeat the hash chain).
CREATE POLICY "Authenticated can read audit log"
ON public.audit_log
FOR SELECT
TO authenticated
USING (true);

CREATE POLICY "Authenticated can append audit log"
ON public.audit_log
FOR INSERT
TO authenticated
WITH CHECK (true);


-- ------------------------------------------------------------------------------
-- [119/208] MIGRATION: 20260811070000_staff_support_tickets.sql
-- ------------------------------------------------------------------------------

-- Firm-staff support tickets. The existing platform_support_tickets /
-- platform_conversations tables and the reply/thread RPCs
-- (reply_customer_support_ticket, get_customer_support_thread) already scope
-- purely by firm_id + requester_id — no role check — so they're reused as-is
-- for staff. Only ticket CREATION needed a staff-facing entry point, since
-- create_customer_support_ticket hard-requires role = 'customer'.

create or replace function public.create_staff_support_ticket(
  p_subject text,
  p_description text,
  p_category text default 'general',
  p_priority text default 'normal'
)
returns public.platform_support_tickets
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_profile public.user_profiles;
  v_ticket public.platform_support_tickets;
  v_priority text := lower(trim(coalesce(p_priority, 'normal')));
begin
  if length(trim(coalesce(p_subject, ''))) < 3 or length(trim(coalesce(p_subject, ''))) > 160 then
    raise exception 'subject must be between 3 and 160 characters' using errcode = '22023';
  end if;
  if length(trim(coalesce(p_description, ''))) < 10 or length(trim(coalesce(p_description, ''))) > 10000 then
    raise exception 'description must be between 10 and 10000 characters' using errcode = '22023';
  end if;
  if v_priority not in ('low', 'normal', 'high', 'urgent') then
    raise exception 'invalid priority' using errcode = '22023';
  end if;

  select * into v_profile from public.user_profiles
  where auth_id = auth.uid() and active and status = 'active' and firm_id is not null
  limit 1;
  if not found then
    raise exception 'No active firm profile for this account' using errcode = '42501';
  end if;

  insert into public.platform_support_tickets
    (ticket_no, firm_id, branch_id, requester_id, category, subject, description, priority)
  values
    ('STF-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS') || '-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6)),
     v_profile.firm_id, v_profile.branch_id, auth.uid(),
     left(trim(coalesce(p_category, 'general')), 80), trim(p_subject), trim(p_description), v_priority)
  returning * into v_ticket;

  return v_ticket;
end;
$$;

revoke all on function public.create_staff_support_ticket(text, text, text, text) from public, anon;
grant execute on function public.create_staff_support_ticket(text, text, text, text) to authenticated;

-- Lists tickets raised by the calling user (staff or customer alike) — used
-- by the staff Support page; customer-portal keeps using get_customer_portal.
create or replace function public.list_my_support_tickets()
returns setof public.platform_support_tickets
language sql
security definer
set search_path = pg_catalog, public
as $$
  select * from public.platform_support_tickets
  where requester_id = auth.uid()
  order by created_at desc;
$$;

revoke all on function public.list_my_support_tickets() from public, anon;
grant execute on function public.list_my_support_tickets() to authenticated;

-- Live chat: stream new replies on a ticket's thread in real time instead of
-- requiring a manual refresh. Existing RLS on platform_conversation_messages
-- (platform_messages_customer_read, scoped to firm_id + requester_id) already
-- covers Realtime's row-level filtering — no policy change needed, just
-- adding the table to the replication publication.
alter publication supabase_realtime add table public.platform_conversation_messages;


-- ------------------------------------------------------------------------------
-- [120/208] MIGRATION: 20260811080000_platform_error_events_and_secrets.sql
-- ------------------------------------------------------------------------------

-- Health monitoring: client-side errors (error-handling.ts's reportUnexpectedError)
-- currently only log to the browser console — the platform owner has no way
-- to see what's breaking for tenants. This table is the missing link.
create table if not exists public.platform_error_events (
  id uuid primary key default gen_random_uuid(),
  firm_id uuid,
  actor_id uuid,
  reference_id text not null,
  category text not null,
  severity text not null,
  context text,
  message text not null,
  technical_message text,
  created_at timestamptz not null default now()
);

create index if not exists platform_error_events_created_idx on public.platform_error_events (created_at desc);
create index if not exists platform_error_events_firm_idx on public.platform_error_events (firm_id);

alter table public.platform_error_events enable row level security;

-- Any authenticated tenant user can report an error (write-only from their
-- side — they can't read other firms' errors back).
create policy platform_error_events_insert on public.platform_error_events
for insert to authenticated
with check (true);

create policy platform_error_events_admin on public.platform_error_events
for all to authenticated
using (public.is_saas_admin())
with check (public.is_saas_admin());

grant insert on public.platform_error_events to authenticated;
grant select, update, delete on public.platform_error_events to authenticated;

-- Platform settings: mark a row as secret so its value is never rendered
-- back to the browser after being saved — the admin settings UI becomes
-- write-only for these (paste a new value; can't read the old one), the
-- practical minimum for storing API keys/webhook secrets in this table.
alter table public.platform_settings add column if not exists is_secret boolean not null default false;


-- ------------------------------------------------------------------------------
-- [121/208] MIGRATION: 20260811090000_platform_setting_secrets.sql
-- ------------------------------------------------------------------------------

-- Secret-aware platform settings: a secret value must never come back to the
-- browser after being saved (masked in the settings list) and must never
-- land in plaintext in the audit trail either (platform_audit_events is
-- readable in the Activity view, which would otherwise leak it right back).
create or replace function public.set_platform_setting(
  p_key text,
  p_value jsonb,
  p_reason text,
  p_is_secret boolean default false
) returns public.platform_settings
language plpgsql
security definer
set search_path = public
as $$
declare
  previous jsonb;
  previous_secret boolean;
  result public.platform_settings;
  audit_before jsonb;
  audit_after jsonb;
begin
  if not public.is_saas_admin() then
    raise exception 'platform admin role required' using errcode = '42501';
  end if;
  if nullif(trim(p_key), '') is null or nullif(trim(p_reason), '') is null then
    raise exception 'setting key and reason are required' using errcode = '22023';
  end if;
  select value, is_secret into previous, previous_secret
  from public.platform_settings where key = trim(p_key);

  insert into public.platform_settings(key, value, is_secret, updated_by)
  values (trim(p_key), coalesce(p_value, '{}'::jsonb), coalesce(p_is_secret, false), auth.uid())
  on conflict (key) do update
    set value = excluded.value, is_secret = excluded.is_secret,
        updated_by = excluded.updated_by, updated_at = now()
  returning * into result;

  audit_before := case when previous_secret then '"[redacted]"'::jsonb else previous end;
  audit_after := case when result.is_secret then '"[redacted]"'::jsonb else result.value end;

  insert into public.platform_audit_events(actor_id, action, target_type, target_id, reason, before_value, after_value)
  values (auth.uid(), 'platform_setting.updated', 'platform_setting', trim(p_key), trim(p_reason), audit_before, audit_after);
  return result;
end;
$$;
revoke execute on function public.set_platform_setting(text,jsonb,text,boolean) from public, anon;
grant execute on function public.set_platform_setting(text,jsonb,text,boolean) to authenticated, service_role;

-- The old 3-arg signature is now redundant; keep it working (defaults
-- is_secret to false) rather than a breaking rename.
drop function if exists public.set_platform_setting(text,jsonb,text);
create or replace function public.set_platform_setting(
  p_key text,
  p_value jsonb,
  p_reason text
) returns public.platform_settings
language sql
security definer
set search_path = public
as $$
  select public.set_platform_setting(p_key, p_value, p_reason, false);
$$;
revoke execute on function public.set_platform_setting(text,jsonb,text) from public, anon;
grant execute on function public.set_platform_setting(text,jsonb,text) to authenticated, service_role;


