-- ------------------------------------------------------------------------------
-- [145/208] MIGRATION: 20260813053000_platform_firm_stats_rpc.sql
-- ------------------------------------------------------------------------------

-- Platform owner aggregate stats for tenant firms.
--
-- This is Supabase-online only. It replaces broad client-side platform summary
-- hydration with one audited aggregate endpoint.

create or replace function public.get_platform_firm_stats()
returns table (
  firm_id uuid,
  invoices bigint,
  invoice_value_minor bigint,
  orders bigint,
  open_orders bigint,
  job_cards bigint,
  users bigint,
  platform_bills bigint
)
language sql
stable
security invoker
set search_path = public
as $$
  with invoice_stats as (
    select
      i.firm_id,
      count(*)::bigint as invoices,
      coalesce(sum(coalesce(i.grand_total_paise, 0)), 0)::bigint as invoice_value_minor
    from public.invoices i
    group by i.firm_id
  ),
  order_stats as (
    select
      o.firm_id,
      count(*)::bigint as orders,
      count(*) filter (
        where lower(coalesce(o.status, '')) not in ('completed', 'cancelled', 'delivered', 'closed')
      )::bigint as open_orders
    from public.orders o
    group by o.firm_id
  ),
  job_stats as (
    select jc.firm_id, count(*)::bigint as job_cards
    from public.job_cards jc
    group by jc.firm_id
  ),
  user_stats as (
    select up.firm_id, count(*)::bigint as users
    from public.user_profiles up
    group by up.firm_id
  ),
  bill_stats as (
    select pbd.firm_id, count(*)::bigint as platform_bills
    from public.platform_billing_documents pbd
    group by pbd.firm_id
  )
  select
    o.id as firm_id,
    coalesce(i.invoices, 0)::bigint as invoices,
    coalesce(i.invoice_value_minor, 0)::bigint as invoice_value_minor,
    coalesce(os.orders, 0)::bigint as orders,
    coalesce(os.open_orders, 0)::bigint as open_orders,
    coalesce(js.job_cards, 0)::bigint as job_cards,
    coalesce(us.users, 0)::bigint as users,
    coalesce(bs.platform_bills, 0)::bigint as platform_bills
  from public.organizations o
  left join invoice_stats i on i.firm_id = o.id
  left join order_stats os on os.firm_id = o.id
  left join job_stats js on js.firm_id = o.id
  left join user_stats us on us.firm_id = o.id
  left join bill_stats bs on bs.firm_id = o.id
  where public.is_saas_admin();
$$;

revoke all on function public.get_platform_firm_stats() from public, anon;
grant execute on function public.get_platform_firm_stats() to authenticated, service_role;


-- ------------------------------------------------------------------------------
-- [146/208] MIGRATION: 20260813054000_billing_outstanding_rpc.sql
-- ------------------------------------------------------------------------------

-- Billing outstanding summary for the web register.
-- Security model: SECURITY INVOKER so public.invoices RLS remains authoritative.

create or replace function public.get_billing_outstanding_summary(p_branch_id text default null)
returns table (
  customer_id text,
  customer_name text,
  phone text,
  amount_paise bigint,
  oldest_created_at timestamptz,
  latest_invoice_id text,
  latest_invoice_no text
)
language sql
security invoker
stable
set search_path = public
as $$
  with open_invoices as (
    select
      i.id,
      i.invoice_no,
      i.customer_id,
      coalesce(nullif(i.data->>'customerName', ''), 'Walk-in Customer') as customer_name,
      nullif(i.data->>'customerPhone', '') as phone,
      i.balance_paise,
      i.created_at,
      row_number() over (
        partition by i.customer_id
        order by i.created_at desc, i.invoice_no desc
      ) as rn
    from public.invoices i
    where i.status <> 'cancelled'
      and i.balance_paise > 0
      and (p_branch_id is null or i.data->>'branchId' = p_branch_id)
  )
  select
    coalesce(open_invoices.customer_id, 'walk_in') as customer_id,
    max(open_invoices.customer_name) as customer_name,
    max(open_invoices.phone) as phone,
    sum(open_invoices.balance_paise)::bigint as amount_paise,
    min(open_invoices.created_at) as oldest_created_at,
    max(open_invoices.id) filter (where open_invoices.rn = 1) as latest_invoice_id,
    max(open_invoices.invoice_no) filter (where open_invoices.rn = 1) as latest_invoice_no
  from open_invoices
  group by coalesce(open_invoices.customer_id, 'walk_in')
  order by sum(open_invoices.balance_paise) desc;
$$;

revoke all on function public.get_billing_outstanding_summary(text) from public;
grant execute on function public.get_billing_outstanding_summary(text) to authenticated;


-- ------------------------------------------------------------------------------
-- [147/208] MIGRATION: 20260813055000_ceo_branch_kpis_rpc.sql
-- ------------------------------------------------------------------------------

create or replace function public.get_ceo_branch_kpis(p_branch_id text)
returns table (
  sales_this_month_paise bigint,
  invoice_count bigint,
  outstanding_paise bigint,
  pending_orders bigint,
  active_job_cards bigint,
  ready_job_cards bigint,
  pending_repairs bigint,
  total_customers bigint
)
language sql
stable
security invoker
set search_path = public
as $$
  with params as (
    select
      nullif(p_branch_id, '') as branch_id,
      date_trunc('month', now()) as month_start
  ),
  month_invoices as (
    select
      coalesce(sum(coalesce(i.grand_total_paise, 0)), 0)::bigint as sales_this_month_paise,
      count(*)::bigint as invoice_count
    from public.invoices i, params p
    where coalesce(i.data->>'branchId', 'MAIN') = coalesce(p.branch_id, 'MAIN')
      and i.created_at >= p.month_start
      and coalesce(i.status, i.data->>'status', '') <> 'cancelled'
  ),
  outstanding_invoices as (
    select coalesce(sum(greatest(coalesce(i.balance_paise, 0), 0)), 0)::bigint as outstanding_paise
    from public.invoices i, params p
    where coalesce(i.data->>'branchId', 'MAIN') = coalesce(p.branch_id, 'MAIN')
      and coalesce(i.status, i.data->>'status', '') <> 'cancelled'
      and coalesce(i.balance_paise, 0) > 0
  ),
  order_counts as (
    select count(*)::bigint as pending_orders
    from public.orders o, params p
    where coalesce(o.data->>'branchId', 'MAIN') = coalesce(p.branch_id, 'MAIN')
      and coalesce(o.status, o.data->>'status', '') in ('pending', 'in_progress', 'ready')
  ),
  job_counts as (
    select
      count(*) filter (
        where coalesce(j.status, j.data->>'status', '') in ('open', 'in_progress')
      )::bigint as active_job_cards,
      count(*) filter (
        where coalesce(j.status, j.data->>'status', '') in ('ready', 'ready_for_billing')
      )::bigint as ready_job_cards
    from public.job_cards j, params p
    where coalesce(j.data->>'branchId', 'MAIN') = coalesce(p.branch_id, 'MAIN')
      and coalesce(j.status, j.data->>'status', '') not in ('closed', 'completed', 'cancelled', 'delivered')
  ),
  repair_counts as (
    select count(*)::bigint as pending_repairs
    from public.repairs r, params p
    where coalesce(r.data->>'branchId', 'MAIN') = coalesce(p.branch_id, 'MAIN')
      and coalesce(r.status, r.data->>'status', '') not in ('delivered', 'cancelled')
  ),
  customer_counts as (
    select count(*)::bigint as total_customers
    from public.people pe, params p
    where coalesce(pe.data->>'branchId', 'MAIN') = coalesce(p.branch_id, 'MAIN')
      and coalesce(pe.type, pe.data->>'type', '') = 'customer'
  )
  select
    month_invoices.sales_this_month_paise,
    month_invoices.invoice_count,
    outstanding_invoices.outstanding_paise,
    order_counts.pending_orders,
    job_counts.active_job_cards,
    job_counts.ready_job_cards,
    repair_counts.pending_repairs,
    customer_counts.total_customers
  from month_invoices, outstanding_invoices, order_counts, job_counts, repair_counts, customer_counts;
$$;

revoke all on function public.get_ceo_branch_kpis(text) from public, anon;
grant execute on function public.get_ceo_branch_kpis(text) to authenticated, service_role;


-- ------------------------------------------------------------------------------
-- [148/208] MIGRATION: 20260813055500_ceo_dashboard_gold_trend_rpc.sql
-- ------------------------------------------------------------------------------

-- CEO dashboard gold trend aggregate.
-- SECURITY INVOKER is intentional: callers see only rows allowed by current RLS.

create or replace function public.get_ceo_gold_trend(p_days integer default 30)
returns table(day date, fine_mg bigint)
language sql
stable
set search_path = public
as $$
  with bounds as (
    select
      (current_date - greatest(1, least(coalesce(p_days, 30), 90)))::date as start_day,
      current_date::date as end_day
  ),
  baseline as (
    select coalesce(sum(gl.net_fine_mg), 0)::bigint as fine_mg
    from public.gold_ledger gl
    cross join bounds b
    where gl.ts < b.start_day
  ),
  daily as (
    select date_trunc('day', gl.ts)::date as day, sum(gl.net_fine_mg)::bigint as delta_mg
    from public.gold_ledger gl
    cross join bounds b
    where gl.ts >= b.start_day
      and gl.ts < b.end_day + interval '1 day'
    group by 1
  ),
  series as (
    select generate_series(b.start_day, b.end_day, interval '1 day')::date as day
    from bounds b
  )
  select
    s.day,
    baseline.fine_mg
      + coalesce(
          sum(coalesce(d.delta_mg, 0)) over (
            order by s.day rows between unbounded preceding and current row
          ),
          0
        )::bigint as fine_mg
  from series s
  cross join baseline
  left join daily d on d.day = s.day
  order by s.day;
$$;

revoke all on function public.get_ceo_gold_trend(integer) from public, anon;
grant execute on function public.get_ceo_gold_trend(integer) to authenticated, service_role;


-- ------------------------------------------------------------------------------
-- [149/208] MIGRATION: 20260813060000_home_dashboard_summary_rpc.sql
-- ------------------------------------------------------------------------------

-- Home dashboard aggregate.
-- SECURITY INVOKER is intentional: all counts/sums respect current caller RLS.

create or replace function public.get_home_dashboard_summary()
returns table(
  vault_gold_mg bigint,
  karigar_gold_mg bigint,
  finished_gold_mg bigint,
  customer_gold_mg bigint,
  jeweller_gold_mg bigint,
  scrap_gold_mg bigint,
  ledger_discrepancy_mg bigint,
  open_orders bigint,
  total_orders bigint,
  available_stock_count bigint,
  today_billing_paise bigint,
  today_invoice_count bigint,
  total_invoice_count bigint,
  today_cash_paise bigint,
  today_upi_paise bigint,
  today_card_paise bigint,
  today_gold_paid_paise bigint,
  today_outstanding_paise bigint,
  today_gold_sold_mg bigint
)
language sql
stable
set search_path = public
as $$
  with ledger as (
    select
      coalesce(sum((bucket_deltas->>'vault')::bigint), 0)::bigint as vault_mg,
      coalesce(sum((bucket_deltas->>'karigar')::bigint), 0)::bigint as karigar_mg,
      coalesce(sum((bucket_deltas->>'finished')::bigint), 0)::bigint as finished_mg,
      coalesce(sum((bucket_deltas->>'customer')::bigint), 0)::bigint as customer_mg,
      coalesce(sum((bucket_deltas->>'jeweller')::bigint), 0)::bigint as jeweller_mg,
      coalesce(sum((bucket_deltas->>'scrap')::bigint), 0)::bigint as scrap_mg,
      coalesce(sum(net_fine_mg), 0)::bigint as total_mg
    from public.gold_ledger
  ),
  today_invoices as (
    select *
    from public.invoices
    where created_at >= current_date
      and created_at < current_date + interval '1 day'
  ),
  payment_totals as (
    select
      coalesce(sum(case when payment->>'mode' = 'cash' then (payment->>'amountPaise')::bigint else 0 end), 0)::bigint as cash_paise,
      coalesce(sum(case when payment->>'mode' = 'upi' then (payment->>'amountPaise')::bigint else 0 end), 0)::bigint as upi_paise,
      coalesce(sum(case when payment->>'mode' = 'card' then (payment->>'amountPaise')::bigint else 0 end), 0)::bigint as card_paise,
      coalesce(sum(case when payment->>'mode' in ('gold_exchange', 'customer_gold_credit') then (payment->>'amountPaise')::bigint else 0 end), 0)::bigint as gold_paid_paise
    from today_invoices ti
    cross join lateral jsonb_array_elements(coalesce(ti.data->'payments', '[]'::jsonb)) payment
  ),
  item_totals as (
    select coalesce(sum((item->>'fineMg')::bigint), 0)::bigint as gold_sold_mg
    from today_invoices ti
    cross join lateral jsonb_array_elements(coalesce(ti.data->'items', '[]'::jsonb)) item
  )
  select
    l.vault_mg,
    l.karigar_mg,
    l.finished_mg,
    l.customer_mg,
    l.jeweller_mg,
    l.scrap_mg,
    (l.total_mg - (l.vault_mg + l.karigar_mg + l.finished_mg + l.customer_mg + l.jeweller_mg + l.scrap_mg))::bigint,
    (select count(*)::bigint from public.orders where status not in ('delivered', 'cancelled')),
    (select count(*)::bigint from public.orders),
    (select count(*)::bigint from public.inventory where status = 'available'),
    coalesce((select sum(grand_total_paise)::bigint from today_invoices), 0)::bigint,
    (select count(*)::bigint from today_invoices),
    (select count(*)::bigint from public.invoices),
    pt.cash_paise,
    pt.upi_paise,
    pt.card_paise,
    pt.gold_paid_paise,
    coalesce((select sum(greatest(balance_paise, 0))::bigint from today_invoices), 0)::bigint,
    it.gold_sold_mg
  from ledger l
  cross join payment_totals pt
  cross join item_totals it;
$$;

revoke all on function public.get_home_dashboard_summary() from public, anon;
grant execute on function public.get_home_dashboard_summary() to authenticated, service_role;


-- ------------------------------------------------------------------------------
-- [150/208] MIGRATION: 20260813061000_auto_populate_firm_id_on_insert.sql
-- ------------------------------------------------------------------------------

-- Client code (base-repository.ts and friends) does not set firm_id on
-- insert for any of the 37 firm-scoped tables from
-- 20260730160000_firm_scope_rls_framework.sql. For a user whose
-- my_firm_id() is non-NULL, that insert now lands firm_id = NULL, which
-- fails that migration's own WITH CHECK (firm_id = my_firm_id() OR
-- (firm_id IS NULL AND my_firm_id() IS NULL)) — e.g. catalog_designs insert
-- during e2e seeding. Root-cause fix: auto-populate firm_id from
-- my_firm_id() before the RLS check runs, once, for every affected table,
-- instead of patching each store/repository call site individually.

CREATE OR REPLACE FUNCTION public.set_firm_id_default()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.firm_id IS NULL THEN
    NEW.firm_id := public.my_firm_id();
  END IF;
  RETURN NEW;
END;
$$;

DO $$
DECLARE
  t text;
  tables text[] := ARRAY[
    'rate_cut_records','gold_ledger','whatsapp_inbox','daily_close','print_logs','salary_rules',
    'worker_transactions','jeweller_transactions','whatsapp_templates','dropdown_masters','app_settings',
    'crm_tasks_meetings','inventory','kyc_documents','stock_movements','people','gold_settlements',
    'crm_interactions','melt_jobs','branch_settings','invitations','repairs','job_process_steps',
    'customer_ledger','communication_logs','job_cards','attendance','manufacturing_bills',
    'attachments','invoices','payments','catalog_designs','document_sequences','worker_settlements',
    'orders','crm_leads_opportunities'
  ];
BEGIN
  FOREACH t IN ARRAY tables LOOP
    IF to_regclass('public.' || t) IS NULL THEN
      CONTINUE;
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = t AND column_name = 'firm_id'
    ) THEN
      CONTINUE;
    END IF;
    EXECUTE format('DROP TRIGGER IF EXISTS trg_set_firm_id_default ON public.%I', t);
    EXECUTE format(
      'CREATE TRIGGER trg_set_firm_id_default BEFORE INSERT ON public.%I FOR EACH ROW EXECUTE FUNCTION public.set_firm_id_default()',
      t
    );
  END LOOP;
END $$;


-- ------------------------------------------------------------------------------
-- [151/208] MIGRATION: 20260813062000_null_invalid_branch_id_on_insert.sql
-- ------------------------------------------------------------------------------

-- Client code defaults selectedBranchId to a placeholder ("MAIN") that
-- predates real branch provisioning and is never an actual row in
-- public.branches (real ids look like "br_xxxxxxxxxxxx"). That placeholder
-- then flows into every branch_id-FK'd table's insert and trips the FK
-- constraint (e.g. attachments_branch_id_fkey, central_parties_default_branch_id_fkey).
-- Root-cause fix: before insert, if branch_id/default_branch_id doesn't
-- match a real branches row, null it out instead of failing the insert —
-- same pattern as 20260813061000's firm_id default, applied once across
-- every affected table instead of validating branch selection at every
-- call site.

CREATE OR REPLACE FUNCTION public.null_invalid_branch_id()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.branch_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.branches WHERE id = NEW.branch_id
  ) THEN
    NEW.branch_id := NULL;
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.null_invalid_default_branch_id()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.default_branch_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.branches WHERE id = NEW.default_branch_id
  ) THEN
    NEW.default_branch_id := NULL;
  END IF;
  RETURN NEW;
END;
$$;

DO $$
DECLARE
  t text;
  -- comm_provider_secrets.branch_id is NOT NULL — excluded; an invalid
  -- branch_id there must fail loudly rather than silently drop the secret's
  -- branch scope.
  tables text[] := ARRAY[
    'workshops','comm_provider_settings','user_profiles','storage_file_metadata','invitations',
    'platform_service_requests','platform_support_tickets','attachments',
    'specialist_work_variances','specialist_payment_clearances','metal_conversions',
    'workshop_process_transactions','customer_gold_deposits','central_activity_events',
    'central_message_threads'
  ];
BEGIN
  FOREACH t IN ARRAY tables LOOP
    IF to_regclass('public.' || t) IS NULL THEN
      CONTINUE;
    END IF;
    EXECUTE format('DROP TRIGGER IF EXISTS trg_null_invalid_branch_id ON public.%I', t);
    EXECUTE format(
      'CREATE TRIGGER trg_null_invalid_branch_id BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.null_invalid_branch_id()',
      t
    );
  END LOOP;

  IF to_regclass('public.central_parties') IS NOT NULL THEN
    EXECUTE 'DROP TRIGGER IF EXISTS trg_null_invalid_default_branch_id ON public.central_parties';
    EXECUTE 'CREATE TRIGGER trg_null_invalid_default_branch_id BEFORE INSERT OR UPDATE ON public.central_parties FOR EACH ROW EXECUTE FUNCTION public.null_invalid_default_branch_id()';
  END IF;
END $$;


