    FOR SELECT
    USING (firm_id = public.my_firm_id() OR public.is_saas_admin());

CREATE POLICY report_snapshots_tenant_insert ON public.report_snapshots
    FOR INSERT
    WITH CHECK (firm_id = public.my_firm_id() OR public.is_saas_admin());


