-- Trial conversion on payment + lifecycle sweep helpers

CREATE OR REPLACE FUNCTION public.convert_trial_to_paid(
  p_organization_id uuid,
  p_plan_id uuid DEFAULT NULL,
  p_reason text DEFAULT 'Razorpay payment captured'
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_plan_id uuid;
BEGIN
  IF p_plan_id IS NOT NULL THEN
    v_plan_id := p_plan_id;
  ELSE
    SELECT plan_id INTO v_plan_id FROM public.organization_subscriptions WHERE organization_id = p_organization_id;
  END IF;

  UPDATE public.organization_subscriptions
  SET
    status = 'active',
    trial_lifecycle_status = 'CONVERTED',
    starts_at = COALESCE(starts_at, now()),
    renews_at = now() + interval '1 year',
    updated_at = now()
  WHERE organization_id = p_organization_id;

  IF v_plan_id IS NOT NULL THEN
    PERFORM public.apply_plan_entitlements(p_organization_id, v_plan_id, p_reason);
  END IF;

  UPDATE public.platform_commercial_leads
  SET lead_stage = 'won', updated_at = now()
  WHERE organization_id = p_organization_id AND lead_stage NOT IN ('won', 'lost');
END;
$$;

-- Extend payment capture to convert trial
CREATE OR REPLACE FUNCTION public.process_razorpay_payment_captured(
  p_razorpay_event_id text,
  p_event_type text,
  p_payload jsonb,
  p_razorpay_payment_id text,
  p_razorpay_order_id text,
  p_amount_paise bigint,
  p_firm_id uuid,
  p_platform_invoice_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_existing uuid;
  v_payment_id uuid;
  v_invoice_id uuid;
  v_plan_id uuid;
BEGIN
  SELECT id INTO v_existing FROM public.webhook_events WHERE razorpay_event_id = p_razorpay_event_id;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'duplicate', true);
  END IF;

  INSERT INTO public.webhook_events (razorpay_event_id, event_type, payload, processed)
  VALUES (p_razorpay_event_id, p_event_type, p_payload, false);

  SELECT id INTO v_payment_id FROM public.platform_payments WHERE razorpay_payment_id = p_razorpay_payment_id;
  IF v_payment_id IS NOT NULL THEN
    UPDATE public.webhook_events SET processed = true, processed_at = now() WHERE razorpay_event_id = p_razorpay_event_id;
    RETURN jsonb_build_object('ok', true, 'duplicate_payment', true);
  END IF;

  INSERT INTO public.platform_payments (
    firm_id, platform_invoice_id, razorpay_payment_id, razorpay_order_id,
    amount_paise, currency, status, captured_at, metadata
  )
  VALUES (
    p_firm_id, p_platform_invoice_id, p_razorpay_payment_id, p_razorpay_order_id,
    p_amount_paise, 'INR', 'CAPTURED', now(),
    jsonb_build_object('event_id', p_razorpay_event_id)
  )
  RETURNING id INTO v_payment_id;

  IF p_platform_invoice_id IS NOT NULL THEN
    UPDATE public.platform_invoices
    SET paid_paise = LEAST(total_paise, paid_paise + p_amount_paise),
        status = CASE WHEN paid_paise + p_amount_paise >= total_paise THEN 'paid' ELSE 'partially_paid' END,
        updated_at = now()
    WHERE id = p_platform_invoice_id
    RETURNING id INTO v_invoice_id;

    SELECT (metadata->>'plan_id')::uuid INTO v_plan_id
    FROM public.platform_invoice_items
    WHERE invoice_id = p_platform_invoice_id AND item_type = 'licence'
    LIMIT 1;

    IF v_plan_id IS NOT NULL THEN
      PERFORM public.convert_trial_to_paid(p_firm_id, v_plan_id, 'Licence payment via Razorpay');
    ELSE
      PERFORM public.convert_trial_to_paid(p_firm_id, NULL, 'Payment via Razorpay');
    END IF;
  END IF;

  IF p_platform_invoice_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.platform_invoice_items
    WHERE invoice_id = p_platform_invoice_id
      AND item_type IN ('credit_topup', 'whatsapp_topup', 'wallet_topup')
  ) THEN
    PERFORM public.grant_tenant_credits(
      (SELECT COALESCE(SUM((metadata->>'credits')::numeric), 0)
       FROM public.platform_invoice_items WHERE invoice_id = p_platform_invoice_id),
      'purchase',
      'Credit top-up via Razorpay',
      jsonb_build_object('razorpay_payment_id', p_razorpay_payment_id),
      p_firm_id
    );
  END IF;

  UPDATE public.webhook_events SET processed = true, processed_at = now() WHERE razorpay_event_id = p_razorpay_event_id;

  RETURN jsonb_build_object('ok', true, 'payment_id', v_payment_id, 'invoice_id', v_invoice_id);
END;
$$;

-- Trial lifecycle sweep (call from scheduler/cron)
CREATE OR REPLACE FUNCTION public.sweep_trial_lifecycle()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_expired int := 0;
  v_expiring int := 0;
  v_follow_up int := 0;
  v_warning_days int;
  v_day2 int;
BEGIN
  SELECT COALESCE((value #>> '{}')::int, 3) INTO v_warning_days
  FROM public.platform_settings WHERE key = 'licensing.trial_expiry_warning_days';
  SELECT COALESCE((value #>> '{}')::int, 2) INTO v_day2
  FROM public.platform_settings WHERE key = 'licensing.trial_follow_up_day_2';

  UPDATE public.organization_subscriptions
  SET trial_lifecycle_status = 'TRIAL_EXPIRED', status = 'expired', updated_at = now()
  WHERE status = 'trial' AND trial_ends_at < now() AND trial_lifecycle_status NOT IN ('CONVERTED', 'TRIAL_EXPIRED');
  GET DIAGNOSTICS v_expired = ROW_COUNT;

  UPDATE public.organization_subscriptions
  SET trial_lifecycle_status = 'TRIAL_EXPIRING', updated_at = now()
  WHERE status = 'trial'
    AND trial_ends_at > now()
    AND trial_ends_at < now() + make_interval(days => v_warning_days)
    AND trial_lifecycle_status = 'TRIAL_ACTIVE';
  GET DIAGNOSTICS v_expiring = ROW_COUNT;

  UPDATE public.platform_commercial_leads
  SET follow_up_due_at = now(), lead_stage = 'contact_pending', updated_at = now()
  WHERE lead_stage = 'new_trial'
    AND trial_started_at < now() - make_interval(days => v_day2)
    AND follow_up_due_at IS NULL;
  GET DIAGNOSTICS v_follow_up = ROW_COUNT;

  PERFORM public.evaluate_trial_expiry();

  RETURN jsonb_build_object('expired', v_expired, 'expiring', v_expiring, 'follow_ups', v_follow_up);
END;
$$;

GRANT EXECUTE ON FUNCTION public.sweep_trial_lifecycle() TO service_role;


-- ------------------------------------------------------------------------------
-- [177/208] MIGRATION: 20260815280000_multi_tenant_identity_subscription_access.sql
-- ------------------------------------------------------------------------------

-- Multi-tenant identity, active business context, and subscription access engine.
-- ONE auth identity → many tenant/product memberships → one active context at a time.
-- Replaces single-firm user_profiles constraint and licence-key runtime authority.

BEGIN;

-- ---------------------------------------------------------------------------
-- PART 1: Allow multiple firm memberships per auth identity
-- ---------------------------------------------------------------------------

ALTER TABLE public.user_profiles
  DROP CONSTRAINT IF EXISTS user_profiles_auth_id_key;

CREATE UNIQUE INDEX IF NOT EXISTS uq_user_profiles_auth_firm
  ON public.user_profiles (auth_id, firm_id)
  WHERE firm_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- PART 2: Canonical membership + active context + preferences
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS public.tenant_memberships (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  auth_user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  product_id TEXT NOT NULL DEFAULT 'ORNEXA',
  membership_kind TEXT NOT NULL DEFAULT 'internal'
    CHECK (membership_kind IN ('internal', 'portal')),
  portal_type TEXT CHECK (portal_type IN ('customer', 'karigar', 'supplier', 'external', 'ceo')),
  portal_type_key TEXT GENERATED ALWAYS AS (COALESCE(portal_type, '')) STORED,
  role TEXT,
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('pending', 'active', 'suspended', 'revoked')),
  user_profile_id UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
  portal_identity_id UUID REFERENCES public.portal_identities(id) ON DELETE SET NULL,
  branch_ids TEXT[],
  invited_by UUID,
  joined_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_active_at TIMESTAMPTZ,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_tenant_membership
  ON public.tenant_memberships (
    auth_user_id, organization_id, product_id, membership_kind, portal_type_key
  );

CREATE INDEX IF NOT EXISTS idx_tenant_memberships_auth
  ON public.tenant_memberships (auth_user_id, status);
CREATE INDEX IF NOT EXISTS idx_tenant_memberships_org
  ON public.tenant_memberships (organization_id, product_id, status);

CREATE TABLE IF NOT EXISTS public.identity_active_context (
  auth_user_id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  product_id TEXT NOT NULL DEFAULT 'ORNEXA',
  portal_type TEXT,
  membership_id UUID REFERENCES public.tenant_memberships(id) ON DELETE SET NULL,
  branch_id TEXT,
  set_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  set_by UUID,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS public.user_preferences (
  auth_user_id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  last_active_organization_id UUID REFERENCES public.organizations(id) ON DELETE SET NULL,
  last_active_product_id TEXT DEFAULT 'ORNEXA',
  last_active_portal_type TEXT,
  preferences JSONB NOT NULL DEFAULT '{}'::jsonb,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Platform SMS provider config (disabled by default — no fake sends)
CREATE TABLE IF NOT EXISTS public.platform_sms_config (
  id TEXT PRIMARY KEY DEFAULT 'default',
  enabled BOOLEAN NOT NULL DEFAULT false,
  provider TEXT,
  sender_id TEXT,
  otp_enabled BOOLEAN NOT NULL DEFAULT false,
  transactional_enabled BOOLEAN NOT NULL DEFAULT false,
  credentials_status TEXT NOT NULL DEFAULT 'not_configured'
    CHECK (credentials_status IN ('not_configured', 'configured', 'invalid', 'disabled')),
  config JSONB NOT NULL DEFAULT '{}'::jsonb,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

INSERT INTO public.platform_sms_config (id, enabled, provider, credentials_status)
VALUES ('default', false, NULL, 'not_configured')
ON CONFLICT (id) DO NOTHING;

-- OTP channel policy (platform defaults)
CREATE TABLE IF NOT EXISTS public.platform_otp_policy (
  id TEXT PRIMARY KEY DEFAULT 'default',
  preferred_channels TEXT[] NOT NULL DEFAULT ARRAY['email', 'whatsapp', 'sms'],
  fallback_enabled BOOLEAN NOT NULL DEFAULT true,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

INSERT INTO public.platform_otp_policy (id)
VALUES ('default')
ON CONFLICT (id) DO NOTHING;

-- Backfill internal memberships from user_profiles
INSERT INTO public.tenant_memberships (
  auth_user_id, organization_id, product_id, membership_kind, portal_type, role, status,
  user_profile_id, branch_ids, joined_at
)
SELECT
  up.auth_id,
  up.firm_id,
  'ORNEXA',
  CASE
    WHEN lower(coalesce(up.role, '')) IN (
      'customer', 'viewer', 'customer portal', 'customer_portal',
      'supplier', 'vendor', 'karigar', 'worker'
    ) THEN 'portal'
    ELSE 'internal'
  END,
  CASE
    WHEN lower(coalesce(up.role, '')) IN ('supplier', 'vendor') THEN 'supplier'
    WHEN lower(coalesce(up.role, '')) IN ('karigar', 'worker') THEN 'karigar'
    WHEN lower(coalesce(up.role, '')) IN ('customer', 'viewer', 'customer portal', 'customer_portal') THEN 'customer'
    WHEN lower(coalesce(up.role, '')) = 'ceo' THEN 'ceo'
    ELSE NULL
  END,
  up.role,
  CASE WHEN up.active AND up.status = 'active' THEN 'active' ELSE 'suspended' END,
  up.id,
  CASE WHEN up.branch_id IS NOT NULL THEN ARRAY[up.branch_id] ELSE NULL END,
  up.created_at
FROM public.user_profiles up
WHERE up.auth_id IS NOT NULL AND up.firm_id IS NOT NULL
ON CONFLICT (auth_user_id, organization_id, product_id, membership_kind, portal_type_key)
DO UPDATE SET
  role = EXCLUDED.role,
  status = EXCLUDED.status,
  user_profile_id = EXCLUDED.user_profile_id,
  updated_at = now();

-- Backfill portal memberships from portal_identities
INSERT INTO public.tenant_memberships (
  auth_user_id, organization_id, product_id, membership_kind, portal_type, status,
  portal_identity_id, user_profile_id, branch_ids, joined_at
)
SELECT
  pi.auth_user_id,
  pi.firm_id,
  'ORNEXA',
  'portal',
  pi.portal_type,
  CASE WHEN pi.status = 'active' THEN 'active' ELSE 'suspended' END,
  pi.id,
  pi.user_profile_id,
  CASE WHEN pi.branch_id IS NOT NULL THEN ARRAY[pi.branch_id] ELSE NULL END,
  pi.created_at
FROM public.portal_identities pi
ON CONFLICT (auth_user_id, organization_id, product_id, membership_kind, portal_type_key)
DO UPDATE SET
  portal_identity_id = EXCLUDED.portal_identity_id,
  status = EXCLUDED.status,
  updated_at = now();

-- Seed active context from existing single-profile users
INSERT INTO public.identity_active_context (auth_user_id, organization_id, product_id, portal_type, branch_id)
SELECT DISTINCT ON (up.auth_id)
  up.auth_id,
  up.firm_id,
  'ORNEXA',
  CASE
    WHEN lower(coalesce(up.role, '')) IN ('supplier', 'vendor') THEN 'supplier'
    WHEN lower(coalesce(up.role, '')) IN ('karigar', 'worker') THEN 'karigar'
    WHEN lower(coalesce(up.role, '')) IN ('customer', 'viewer', 'customer portal', 'customer_portal') THEN 'customer'
    ELSE NULL
  END,
  up.branch_id
FROM public.user_profiles up
WHERE up.auth_id IS NOT NULL AND up.firm_id IS NOT NULL AND up.active AND up.status = 'active'
ORDER BY up.auth_id, up.updated_at DESC
ON CONFLICT (auth_user_id) DO NOTHING;

-- ---------------------------------------------------------------------------
-- PART 3: Active firm resolution (server-authoritative)
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.my_active_firm_id()
RETURNS UUID
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_ctx UUID;
  v_fallback UUID;
BEGIN
  IF auth.uid() IS NULL THEN RETURN NULL; END IF;
  IF public.is_saas_admin() THEN RETURN NULL; END IF;

  SELECT iac.organization_id INTO v_ctx
  FROM public.identity_active_context iac
  WHERE iac.auth_user_id = auth.uid();

  IF v_ctx IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.tenant_memberships tm
    WHERE tm.auth_user_id = auth.uid()
      AND tm.organization_id = v_ctx
      AND tm.status = 'active'
  ) THEN
    RETURN v_ctx;
  END IF;

  SELECT tm.organization_id INTO v_fallback
  FROM public.tenant_memberships tm
  WHERE tm.auth_user_id = auth.uid() AND tm.status = 'active'
  ORDER BY tm.last_active_at DESC NULLS LAST, tm.joined_at DESC
  LIMIT 1;

  IF v_fallback IS NOT NULL THEN
    INSERT INTO public.identity_active_context (auth_user_id, organization_id, product_id)
    VALUES (auth.uid(), v_fallback, 'ORNEXA')
    ON CONFLICT (auth_user_id) DO UPDATE
      SET organization_id = EXCLUDED.organization_id, set_at = now();
  END IF;

  RETURN v_fallback;
END;
$$;

CREATE OR REPLACE FUNCTION public.my_firm_id()
RETURNS UUID
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
  SELECT public.my_active_firm_id();
$$;

-- ---------------------------------------------------------------------------
-- PART 4: Membership listing + active context switch
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.get_my_memberships(
  p_product_id TEXT DEFAULT 'ORNEXA',
  p_portal_type TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_active UUID;
BEGIN
  IF auth.uid() IS NULL THEN RETURN '[]'::jsonb; END IF;

  SELECT organization_id INTO v_active
  FROM public.identity_active_context WHERE auth_user_id = auth.uid();

  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'membership_id', tm.id,
      'organization_id', tm.organization_id,
      'organization_name', o.name,
      'organization_slug', o.slug,
      'product_id', tm.product_id,
      'membership_kind', tm.membership_kind,
      'portal_type', tm.portal_type,
      'role', tm.role,
      'status', tm.status,
      'branch_ids', tm.branch_ids,
      'is_active', tm.organization_id = v_active,
      'subscription_status', os.status,
      'trial_ends_at', os.trial_ends_at,
      'renews_at', os.renews_at
    ) ORDER BY o.name)
    FROM public.tenant_memberships tm
    JOIN public.organizations o ON o.id = tm.organization_id
    LEFT JOIN public.organization_subscriptions os ON os.organization_id = tm.organization_id
    WHERE tm.auth_user_id = auth.uid()
      AND tm.status = 'active'
      AND (p_product_id IS NULL OR tm.product_id = p_product_id)
      AND (p_portal_type IS NULL OR tm.portal_type = p_portal_type OR tm.membership_kind = 'internal')
  ), '[]'::jsonb);
END;
$$;

CREATE OR REPLACE FUNCTION public.set_active_tenant_context(
  p_organization_id UUID,
  p_product_id TEXT DEFAULT 'ORNEXA',
  p_portal_type TEXT DEFAULT NULL,
  p_branch_id TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_membership public.tenant_memberships;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_membership
  FROM public.tenant_memberships tm
  WHERE tm.auth_user_id = auth.uid()
    AND tm.organization_id = p_organization_id
    AND tm.product_id = COALESCE(p_product_id, 'ORNEXA')
    AND tm.status = 'active'
    AND (
      p_portal_type IS NULL
      OR tm.portal_type = p_portal_type
      OR tm.membership_kind = 'internal'
    )
  ORDER BY CASE WHEN tm.portal_type = p_portal_type THEN 0 ELSE 1 END
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No authorized membership for this business' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.identity_active_context (
    auth_user_id, organization_id, product_id, portal_type, membership_id, branch_id, set_by
  ) VALUES (
    auth.uid(), p_organization_id, COALESCE(p_product_id, 'ORNEXA'),
    COALESCE(p_portal_type, v_membership.portal_type), v_membership.id, p_branch_id, auth.uid()
  )
  ON CONFLICT (auth_user_id) DO UPDATE SET
    organization_id = EXCLUDED.organization_id,
    product_id = EXCLUDED.product_id,
    portal_type = EXCLUDED.portal_type,
    membership_id = EXCLUDED.membership_id,
    branch_id = EXCLUDED.branch_id,
    set_at = now(),
    set_by = auth.uid();

  UPDATE public.tenant_memberships
  SET last_active_at = now(), updated_at = now()
  WHERE id = v_membership.id;

  INSERT INTO public.user_preferences (auth_user_id, last_active_organization_id, last_active_product_id, last_active_portal_type, updated_at)
  VALUES (auth.uid(), p_organization_id, COALESCE(p_product_id, 'ORNEXA'), p_portal_type, now())
  ON CONFLICT (auth_user_id) DO UPDATE SET
    last_active_organization_id = EXCLUDED.last_active_organization_id,
    last_active_product_id = EXCLUDED.last_active_product_id,
    last_active_portal_type = EXCLUDED.last_active_portal_type,
    updated_at = now();

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'product_id', COALESCE(p_product_id, 'ORNEXA'),
    'portal_type', COALESCE(p_portal_type, v_membership.portal_type),
    'membership_id', v_membership.id,
    'role', v_membership.role
  );
END;
$$;

-- Update portal context to respect active tenant
CREATE OR REPLACE FUNCTION public.get_my_portal_context(p_portal_type TEXT DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_identity public.portal_identities;
  v_parties JSONB;
  v_active_firm UUID;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  v_active_firm := public.my_active_firm_id();

  SELECT * INTO v_identity
  FROM public.portal_identities pi
  WHERE pi.auth_user_id = auth.uid()
    AND pi.status = 'active'
    AND (v_active_firm IS NULL OR pi.firm_id = v_active_firm)
    AND (p_portal_type IS NULL OR pi.portal_type = lower(p_portal_type))
  ORDER BY CASE WHEN pi.firm_id = v_active_firm THEN 0 ELSE 1 END, pi.updated_at DESC
  LIMIT 1;

  IF NOT FOUND THEN RETURN NULL; END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'party_id', ppl.party_id,
    'link_role', ppl.link_role,
    'allowed_branch_ids', ppl.allowed_branch_ids
  ) ORDER BY CASE WHEN ppl.link_role = 'primary' THEN 0 ELSE 1 END), '[]'::jsonb)
  INTO v_parties
  FROM public.portal_party_links ppl
  WHERE ppl.portal_identity_id = v_identity.id AND ppl.is_active = true;

  RETURN jsonb_build_object(
    'identity_id', v_identity.id,
    'firm_id', v_identity.firm_id,
    'portal_type', v_identity.portal_type,
    'branch_id', v_identity.branch_id,
    'party_links', v_parties
  );
END;
$$;

-- ---------------------------------------------------------------------------
-- PART 5: Central subscription access engine (replaces licence-key gate)
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.resolve_subscription_access(
  p_organization_id UUID DEFAULT NULL,
  p_product_id TEXT DEFAULT 'ORNEXA'
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_firm_id UUID;
  v_sub public.organization_subscriptions;
  v_plan public.platform_plans;
  v_status TEXT;
  v_access TEXT;
  v_message TEXT;
  v_valid BOOLEAN := false;
  v_trial_ends_ms BIGINT;
  v_renews_ms BIGINT;
  v_days_remaining INT;
BEGIN
  IF public.is_saas_admin() THEN
    RETURN jsonb_build_object(
      'access', 'granted', 'status', 'platform_owner', 'valid', true,
      'message', 'Platform owner access.', 'edition', 'Platform', 'features', '{}'::jsonb
    );
  END IF;

  v_firm_id := COALESCE(p_organization_id, public.my_active_firm_id());
  IF v_firm_id IS NULL THEN
    RETURN jsonb_build_object(
      'access', 'denied', 'status', 'no_tenant', 'valid', false,
      'message', 'No active business context.'
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.tenant_memberships tm
    WHERE tm.auth_user_id = auth.uid()
      AND tm.organization_id = v_firm_id
      AND tm.status = 'active'
  ) THEN
    RETURN jsonb_build_object(
      'access', 'denied', 'status', 'no_membership', 'valid', false,
      'message', 'You are not authorized for this business.', 'organization_id', v_firm_id
    );
  END IF;

  SELECT * INTO v_sub
  FROM public.organization_subscriptions
  WHERE organization_id = v_firm_id
  ORDER BY created_at DESC LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'access', 'denied', 'status', 'no_subscription', 'valid', false,
      'message', 'No subscription found for this business.',
      'organization_id', v_firm_id
    );
  END IF;

  SELECT * INTO v_plan FROM public.platform_plans WHERE id = v_sub.plan_id;

  v_trial_ends_ms := CASE WHEN v_sub.trial_ends_at IS NULL THEN NULL
    ELSE (extract(epoch from v_sub.trial_ends_at) * 1000)::bigint END;
  v_renews_ms := CASE WHEN v_sub.renews_at IS NULL THEN NULL
    ELSE (extract(epoch from v_sub.renews_at) * 1000)::bigint END;

  IF v_sub.status = 'trial' AND v_sub.trial_ends_at IS NOT NULL AND v_sub.trial_ends_at > now() THEN
    v_valid := true; v_status := 'TRIAL_ACTIVE'; v_access := 'granted';
    v_days_remaining := GREATEST(0, ceil(extract(epoch from (v_sub.trial_ends_at - now())) / 86400)::int);
    v_message := format('Trial active — %s day(s) remaining.', v_days_remaining);
  ELSIF v_sub.status = 'trial' AND v_sub.trial_ends_at IS NOT NULL AND v_sub.trial_ends_at <= now() + interval '3 days' AND v_sub.trial_ends_at > now() THEN
    v_valid := true; v_status := 'TRIAL_EXPIRING'; v_access := 'granted';
    v_message := 'Trial expiring soon.';
  ELSIF v_sub.status = 'trial' AND (v_sub.trial_ends_at IS NULL OR v_sub.trial_ends_at <= now()) THEN
    v_valid := false; v_status := 'TRIAL_EXPIRED'; v_access := 'subscription_required';
    v_message := 'Your trial has ended. Renew or choose a plan to continue.';
  ELSIF v_sub.status = 'active' THEN
    v_valid := true; v_status := 'ACTIVE'; v_access := 'granted';
    v_message := 'Subscription active.';
  ELSIF v_sub.status = 'grace_period' OR v_sub.status = 'past_due' THEN
    v_valid := true; v_status := upper(v_sub.status); v_access := 'granted_limited';
    v_message := 'Subscription needs attention — limited access.';
  ELSIF v_sub.status = 'payment_pending' THEN
    v_valid := false; v_status := 'PAYMENT_PENDING'; v_access := 'billing_only';
    v_message := 'Payment is pending for this business.';
  ELSIF v_sub.status = 'suspended' THEN
    v_valid := false; v_status := 'SUSPENDED'; v_access := 'denied';
    v_message := 'This business subscription is suspended.';
  ELSIF v_sub.status = 'cancelled' THEN
    v_valid := false; v_status := 'CANCELLED'; v_access := 'denied';
    v_message := 'This business subscription was cancelled.';
  ELSE
    v_valid := false; v_status := 'EXPIRED'; v_access := 'subscription_required';
    v_message := 'Your subscription needs attention.';
  END IF;

  RETURN jsonb_build_object(
    'access', v_access,
    'status', v_status,
    'valid', v_valid,
    'message', v_message,
    'organization_id', v_firm_id,
    'product_id', p_product_id,
    'trialEndsAt', v_trial_ends_ms,
    'expiry', v_renews_ms,
    'daysRemaining', v_days_remaining,
    'edition', coalesce(v_plan.edition_code, v_plan.name, 'Trial'),
    'planCode', v_plan.code,
    'planName', v_plan.name,
    'limits', public.get_organization_plan_limits(v_firm_id),
    'features', (
      SELECT coalesce(jsonb_object_agg(of.feature_key, of.enabled), '{}'::jsonb)
      FROM public.organization_features of WHERE of.organization_id = v_firm_id
    )
  );
END;
$$;

-- Point legacy entitlement RPC at subscription engine
CREATE OR REPLACE FUNCTION public.get_my_tenant_subscription_entitlement()
RETURNS JSON
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
  SELECT public.resolve_subscription_access(NULL, 'ORNEXA')::json;
$$;

-- Add membership on invitation accept (existing auth user)
CREATE OR REPLACE FUNCTION public.add_tenant_membership_for_invite(
  p_auth_user_id UUID,
  p_organization_id UUID,
  p_role TEXT DEFAULT NULL,
  p_portal_type TEXT DEFAULT NULL,
  p_user_profile_id UUID DEFAULT NULL,
  p_portal_identity_id UUID DEFAULT NULL,
  p_branch_id TEXT DEFAULT NULL
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_id UUID;
  v_kind TEXT;
BEGIN
  v_kind := CASE WHEN p_portal_type IS NOT NULL THEN 'portal' ELSE 'internal' END;

  INSERT INTO public.tenant_memberships (
    auth_user_id, organization_id, product_id, membership_kind, portal_type, role, status,
    user_profile_id, portal_identity_id, branch_ids
  ) VALUES (
    p_auth_user_id, p_organization_id, 'ORNEXA', v_kind, p_portal_type, p_role, 'active',
    p_user_profile_id, p_portal_identity_id,
    CASE WHEN p_branch_id IS NOT NULL THEN ARRAY[p_branch_id] ELSE NULL END
  )
  ON CONFLICT (auth_user_id, organization_id, product_id, membership_kind, portal_type_key)
  DO UPDATE SET
    role = COALESCE(EXCLUDED.role, tenant_memberships.role),
    status = 'active',
    user_profile_id = COALESCE(EXCLUDED.user_profile_id, tenant_memberships.user_profile_id),
    portal_identity_id = COALESCE(EXCLUDED.portal_identity_id, tenant_memberships.portal_identity_id),
    updated_at = now()
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;

-- RLS
ALTER TABLE public.tenant_memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.identity_active_context ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_preferences ENABLE ROW LEVEL SECURITY;

CREATE POLICY tenant_memberships_self_read ON public.tenant_memberships
  FOR SELECT TO authenticated USING (auth_user_id = auth.uid() OR public.is_saas_admin());

CREATE POLICY identity_active_context_self ON public.identity_active_context
  FOR ALL TO authenticated USING (auth_user_id = auth.uid())
  WITH CHECK (auth_user_id = auth.uid());

CREATE POLICY user_preferences_self ON public.user_preferences
  FOR ALL TO authenticated USING (auth_user_id = auth.uid())
  WITH CHECK (auth_user_id = auth.uid());

REVOKE ALL ON FUNCTION public.my_active_firm_id() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.get_my_memberships(TEXT, TEXT) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.set_active_tenant_context(UUID, TEXT, TEXT, TEXT) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.resolve_subscription_access(UUID, TEXT) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.add_tenant_membership_for_invite(UUID, UUID, TEXT, TEXT, UUID, UUID, TEXT) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION public.my_active_firm_id() TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_my_memberships(TEXT, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.set_active_tenant_context(UUID, TEXT, TEXT, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.resolve_subscription_access(UUID, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.add_tenant_membership_for_invite(UUID, UUID, TEXT, TEXT, UUID, UUID, TEXT) TO service_role;

COMMIT;


-- ------------------------------------------------------------------------------
-- [178/208] MIGRATION: 20260816010000_platform_payment_engine_v1.sql
-- ------------------------------------------------------------------------------

-- Platform Payment Engine v1 — fulfillment allocation, cash policy, receipts
-- Chain: Invoice → Razorpay/Cash → Payment → Allocation → Entitlements/Credits → Receipt

-- ============================================================================
-- 1. Fulfillment idempotency ledger (prevents duplicate credits/renewals)
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.platform_invoice_fulfillments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  platform_payment_id uuid NOT NULL REFERENCES public.platform_payments(id) ON DELETE CASCADE,
  platform_invoice_id uuid NOT NULL REFERENCES public.platform_invoices(id) ON DELETE CASCADE,
  invoice_item_id uuid REFERENCES public.platform_invoice_items(id) ON DELETE SET NULL,
  fulfillment_type text NOT NULL,
  amount_paise bigint NOT NULL DEFAULT 0,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  fulfilled_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (platform_payment_id, invoice_item_id, fulfillment_type)
);
CREATE INDEX IF NOT EXISTS idx_platform_invoice_fulfillments_invoice
  ON public.platform_invoice_fulfillments(platform_invoice_id);

ALTER TABLE public.platform_invoice_fulfillments ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS platform_invoice_fulfillments_tenant ON public.platform_invoice_fulfillments;
CREATE POLICY platform_invoice_fulfillments_tenant ON public.platform_invoice_fulfillments
  FOR SELECT TO authenticated
  USING (
    public.is_saas_admin()
    OR platform_invoice_id IN (
      SELECT id FROM public.platform_invoices WHERE firm_id = public.my_firm_id()
    )
  );

-- ============================================================================
-- 2. Payment receipts (generated after successful allocation)
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.platform_receipts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  receipt_no text NOT NULL UNIQUE,
  firm_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE RESTRICT,
  platform_invoice_id uuid REFERENCES public.platform_invoices(id) ON DELETE SET NULL,
  platform_payment_id uuid REFERENCES public.platform_payments(id) ON DELETE SET NULL,
  cash_collection_id uuid REFERENCES public.cash_collections(id) ON DELETE SET NULL,
  amount_paise bigint NOT NULL CHECK (amount_paise >= 0),
  payment_method text NOT NULL CHECK (payment_method IN ('razorpay', 'cash', 'bank_transfer', 'adjustment')),
  issued_at timestamptz NOT NULL DEFAULT now(),
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_platform_receipts_firm ON public.platform_receipts(firm_id, issued_at DESC);

ALTER TABLE public.platform_receipts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS platform_receipts_tenant ON public.platform_receipts;
CREATE POLICY platform_receipts_tenant ON public.platform_receipts
  FOR SELECT TO authenticated
  USING (public.is_saas_admin() OR firm_id = public.my_firm_id());

-- ============================================================================
-- 3. Fix trial conversion — persist purchased plan_id
-- ============================================================================
CREATE OR REPLACE FUNCTION public.convert_trial_to_paid(
  p_organization_id uuid,
  p_plan_id uuid DEFAULT NULL,
  p_reason text DEFAULT 'Payment captured'
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_plan_id uuid;
BEGIN
  IF p_plan_id IS NOT NULL THEN
    v_plan_id := p_plan_id;
  ELSE
    SELECT plan_id INTO v_plan_id FROM public.organization_subscriptions WHERE organization_id = p_organization_id;
  END IF;

  UPDATE public.organization_subscriptions
  SET
    status = 'active',
    plan_id = COALESCE(v_plan_id, plan_id),
    trial_lifecycle_status = 'CONVERTED',
    starts_at = COALESCE(starts_at, now()),
    renews_at = COALESCE(renews_at, now() + interval '1 year'),
    updated_at = now()
  WHERE organization_id = p_organization_id;

  IF v_plan_id IS NOT NULL THEN
    PERFORM public.apply_plan_entitlements(p_organization_id, v_plan_id, p_reason);
  END IF;

  UPDATE public.platform_commercial_leads
  SET lead_stage = 'won', updated_at = now()
  WHERE organization_id = p_organization_id AND lead_stage NOT IN ('won', 'lost');
END;
$$;

-- ============================================================================
-- 4. Cash geography policy helper (configurable — not hardcoded in app code)
-- ============================================================================
CREATE OR REPLACE FUNCTION public.is_cash_collection_location_allowed(
  p_location text,
  p_override_reason text DEFAULT NULL,
  p_override_by uuid DEFAULT NULL
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_policy jsonb;
  v_locations jsonb;
  v_norm text;
BEGIN
  IF p_override_reason IS NOT NULL AND length(trim(p_override_reason)) > 0
     AND p_override_by IS NOT NULL AND public.is_saas_admin() THEN
    RETURN true;
  END IF;

  SELECT default_collection_policy INTO v_policy FROM public.payment_configuration WHERE id = 1;
  v_locations := COALESCE(v_policy->'cash_allowed_locations', '[]'::jsonb);
  v_norm := lower(trim(p_location));

  RETURN EXISTS (
    SELECT 1 FROM jsonb_array_elements_text(v_locations) loc
    WHERE lower(trim(loc)) = v_norm
  );
END;
$$;

-- ============================================================================
-- 5. Create commercial invoice from rate-card / plan metadata (no hardcoded prices)
-- ============================================================================
CREATE OR REPLACE FUNCTION public.create_platform_commercial_invoice(
  p_firm_id uuid,
  p_billing_name text,
  p_lines jsonb,
  p_billing_gstin text DEFAULT NULL,
  p_billing_address text DEFAULT NULL,
  p_due_days int DEFAULT 15,
  p_terms text DEFAULT NULL,
  p_primary_item_type text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_invoice_id uuid;
  v_invoice_no text;
  v_line jsonb;
  v_item_type text;
  v_qty numeric;
  v_unit bigint;
  v_tax numeric;
  v_amount bigint;
  v_desc text;
  v_meta jsonb;
BEGIN
  IF NOT public.is_saas_admin() AND p_firm_id IS DISTINCT FROM public.my_firm_id() THEN
    RAISE EXCEPTION 'Unauthorized firm' USING ERRCODE = '42501';
  END IF;

  IF p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'At least one invoice line required';
  END IF;

  v_invoice_no := 'AVS-' || to_char(now(), 'YYMMDD') || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 6);

  INSERT INTO public.platform_invoices (
    invoice_no, firm_id, billing_name, billing_gstin, billing_address,
    due_date, item_type, status, terms, created_by
  )
  VALUES (
    v_invoice_no, p_firm_id, p_billing_name, p_billing_gstin, p_billing_address,
    current_date + COALESCE(p_due_days, 15),
    p_primary_item_type, 'sent', p_terms, auth.uid()
  )
  RETURNING id INTO v_invoice_id;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_item_type := v_line->>'item_type';
    IF NOT public.is_valid_platform_item_type(v_item_type) THEN
      RAISE EXCEPTION 'Invalid item_type: %', v_item_type;
    END IF;
    v_qty := COALESCE((v_line->>'quantity')::numeric, 1);
    v_unit := COALESCE((v_line->>'unit_price_paise')::bigint, 0);
    v_tax := COALESCE((v_line->>'tax_rate_pct')::numeric, 0);
    v_amount := round(v_qty * v_unit * (1 + v_tax / 100.0))::bigint;
    v_desc := COALESCE(v_line->>'description', v_item_type);
    v_meta := COALESCE(v_line->'metadata', '{}'::jsonb);

    INSERT INTO public.platform_invoice_items (
      invoice_id, description, item_type, quantity, unit_price_paise, tax_rate_pct, amount_paise, metadata
    )
    VALUES (v_invoice_id, v_desc, v_item_type, v_qty, v_unit, v_tax, v_amount, v_meta);
  END LOOP;

  PERFORM public.audit_log_append(
    'platform_invoice.create', 'platform_invoices', v_invoice_id::text, NULL,
    jsonb_build_object('firm_id', p_firm_id, 'invoice_no', v_invoice_no)
  );

  RETURN jsonb_build_object('ok', true, 'invoice_id', v_invoice_id, 'invoice_no', v_invoice_no);
END;
$$;

REVOKE ALL ON FUNCTION public.create_platform_commercial_invoice(uuid, text, jsonb, text, text, int, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_platform_commercial_invoice(uuid, text, jsonb, text, text, int, text, text) TO authenticated, service_role;

-- ============================================================================
-- 6. Invoice payment allocation — idempotent fulfillment per line type
-- ============================================================================
CREATE OR REPLACE FUNCTION public.allocate_platform_invoice_payment(
  p_payment_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_payment record;
  v_item record;
  v_credits numeric;
  v_plan_id uuid;
  v_receipt_no text;
  v_fulfillment_count int := 0;
  v_amc_months int;
BEGIN
  SELECT * INTO v_payment FROM public.platform_payments WHERE id = p_payment_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'payment_not_found');
  END IF;
  IF v_payment.platform_invoice_id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'skipped', 'no_invoice');
  END IF;

  FOR v_item IN
    SELECT * FROM public.platform_invoice_items WHERE invoice_id = v_payment.platform_invoice_id
  LOOP
  IF EXISTS (
    SELECT 1 FROM public.platform_invoice_fulfillments
    WHERE platform_payment_id = p_payment_id AND invoice_item_id = v_item.id AND fulfillment_type = v_item.item_type
  ) THEN
    CONTINUE;
  END IF;

  CASE v_item.item_type
    WHEN 'licence', 'plan_upgrade' THEN
      v_plan_id := (v_item.metadata->>'plan_id')::uuid;
      IF v_plan_id IS NOT NULL THEN
        PERFORM public.convert_trial_to_paid(v_payment.firm_id, v_plan_id, 'Invoice ' || v_item.item_type);
      END IF;
    WHEN 'plan_renewal', 'amc' THEN
      v_amc_months := COALESCE((v_item.metadata->>'months')::int, 12);
      UPDATE public.organization_subscriptions
      SET renews_at = COALESCE(renews_at, now()) + make_interval(months => v_amc_months),
          status = 'active',
          updated_at = now()
      WHERE organization_id = v_payment.firm_id;
    WHEN 'credit_topup', 'wallet_topup' THEN
      v_credits := COALESCE((v_item.metadata->>'credits')::numeric, 0);
      IF v_credits > 0 THEN
        PERFORM public.grant_tenant_credits(
          v_credits, 'purchase', 'Credit top-up — invoice line',
          jsonb_build_object('payment_id', p_payment_id, 'invoice_item_id', v_item.id),
          v_payment.firm_id
        );
      END IF;
    WHEN 'whatsapp_topup' THEN
      v_credits := COALESCE((v_item.metadata->>'credits')::numeric, (v_item.metadata->>'whatsapp_credits')::numeric, 0);
      IF v_credits > 0 THEN
        PERFORM public.grant_tenant_credits(
          v_credits, 'purchase', 'WhatsApp credit top-up',
          jsonb_build_object('payment_id', p_payment_id, 'service', 'whatsapp'),
          v_payment.firm_id
        );
      END IF;
    ELSE
      NULL; -- addon, branch_addon, etc. — audited via fulfillment row; PO applies entitlements manually or via future hooks
  END CASE;

  INSERT INTO public.platform_invoice_fulfillments (
    platform_payment_id, platform_invoice_id, invoice_item_id, fulfillment_type, amount_paise, metadata
  )
  VALUES (
    p_payment_id, v_payment.platform_invoice_id, v_item.id, v_item.item_type, v_item.amount_paise, v_item.metadata
  );
  v_fulfillment_count := v_fulfillment_count + 1;
  END LOOP;

  IF NOT EXISTS (SELECT 1 FROM public.platform_receipts WHERE platform_payment_id = p_payment_id) THEN
    v_receipt_no := 'RCP-' || to_char(now(), 'YYMMDD') || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 6);
    INSERT INTO public.platform_receipts (
      receipt_no, firm_id, platform_invoice_id, platform_payment_id, cash_collection_id,
      amount_paise, payment_method, metadata
    )
    VALUES (
      v_receipt_no, v_payment.firm_id, v_payment.platform_invoice_id, p_payment_id,
      NULLIF(v_payment.metadata->>'cash_collection_id', '')::uuid,
      v_payment.amount_paise, COALESCE(v_payment.method, 'razorpay'),
      jsonb_build_object(
        'razorpay_payment_id', v_payment.razorpay_payment_id,
        'cash_collection_id', v_payment.metadata->>'cash_collection_id'
      )
    );
  END IF;

  PERFORM public.audit_log_append(
    'platform_payment.allocated', 'platform_payments', p_payment_id::text, NULL,
    jsonb_build_object('fulfillments', v_fulfillment_count)
  );

  RETURN jsonb_build_object('ok', true, 'fulfillments', v_fulfillment_count);
END;
$$;

REVOKE ALL ON FUNCTION public.allocate_platform_invoice_payment(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.allocate_platform_invoice_payment(uuid) TO service_role;

-- ============================================================================
-- 7. Cash collection — propose + confirm with geography policy
-- ============================================================================
CREATE OR REPLACE FUNCTION public.propose_cash_collection(
  p_firm_id uuid,
  p_platform_invoice_id uuid,
  p_amount_paise bigint,
  p_collection_location text,
  p_collector text,
  p_receipt_no text DEFAULT NULL,
  p_notes text DEFAULT NULL,
  p_proof_attachment_url text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_id uuid;
  v_invoice record;
BEGIN
  IF NOT public.is_saas_admin() THEN
    RAISE EXCEPTION 'Only Platform Owner can record cash collections' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_invoice FROM public.platform_invoices WHERE id = p_platform_invoice_id AND firm_id = p_firm_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice not found for firm';
  END IF;

  IF p_amount_paise <= 0 OR p_amount_paise > v_invoice.balance_paise THEN
    RAISE EXCEPTION 'Invalid collection amount';
  END IF;

  INSERT INTO public.cash_collections (
    firm_id, platform_invoice_id, amount_paise, collection_location,
    collector, receipt_no, notes, proof_attachment_url, status
  )
  VALUES (
    p_firm_id, p_platform_invoice_id, p_amount_paise, trim(p_collection_location),
    trim(p_collector), p_receipt_no, p_notes, p_proof_attachment_url, 'pending'
  )
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('ok', true, 'cash_collection_id', v_id, 'requires_override',
    NOT public.is_cash_collection_location_allowed(p_collection_location, NULL, NULL));
END;
$$;

CREATE OR REPLACE FUNCTION public.confirm_cash_collection(
  p_cash_collection_id uuid,
  p_override_reason text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_cash record;
  v_payment_id uuid;
  v_receipt_no text;
  v_allowed boolean;
BEGIN
  IF NOT public.is_saas_admin() THEN
    RAISE EXCEPTION 'Only Platform Owner can confirm cash' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_cash FROM public.cash_collections WHERE id = p_cash_collection_id FOR UPDATE;
  IF NOT FOUND OR v_cash.status <> 'pending' THEN
    RAISE EXCEPTION 'Cash collection not pending';
  END IF;

  v_allowed := public.is_cash_collection_location_allowed(
    v_cash.collection_location, p_override_reason, auth.uid()
  );
  IF NOT v_allowed THEN
    RAISE EXCEPTION 'Cash not allowed outside approved geography. Record override with reason.';
  END IF;

  IF p_override_reason IS NOT NULL AND length(trim(p_override_reason)) > 0 THEN
    UPDATE public.cash_collections
    SET override_reason = p_override_reason, override_by = auth.uid(), override_at = now()
    WHERE id = p_cash_collection_id;
    PERFORM public.audit_log_append(
      'cash_collection.override', 'cash_collections', p_cash_collection_id::text, NULL,
      jsonb_build_object('reason', p_override_reason, 'location', v_cash.collection_location)
    );
  END IF;

  INSERT INTO public.platform_payments (
    firm_id, platform_invoice_id, amount_paise, currency, status, captured_at, method, metadata
  )
  VALUES (
    v_cash.firm_id, v_cash.platform_invoice_id, v_cash.amount_paise, 'INR', 'CAPTURED', now(), 'cash',
    jsonb_build_object('cash_collection_id', v_cash.id, 'collector', v_cash.collector, 'location', v_cash.collection_location)
  )
  RETURNING id INTO v_payment_id;

  UPDATE public.platform_invoices
  SET paid_paise = LEAST(total_paise, paid_paise + v_cash.amount_paise),
      status = CASE WHEN paid_paise + v_cash.amount_paise >= total_paise THEN 'paid' ELSE 'partially_paid' END,
      updated_at = now()
  WHERE id = v_cash.platform_invoice_id;

  UPDATE public.cash_collections
  SET status = 'confirmed', confirmed_by = auth.uid(), collected_at = COALESCE(collected_at, now())
  WHERE id = p_cash_collection_id;

  PERFORM public.allocate_platform_invoice_payment(v_payment_id);

  PERFORM public.audit_log_append(
    'cash_collection.confirmed', 'cash_collections', p_cash_collection_id::text, NULL,
    jsonb_build_object('payment_id', v_payment_id, 'amount_paise', v_cash.amount_paise)
  );

  RETURN jsonb_build_object('ok', true, 'payment_id', v_payment_id);
END;
$$;

REVOKE ALL ON FUNCTION public.propose_cash_collection(uuid, uuid, bigint, text, text, text, text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.confirm_cash_collection(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.propose_cash_collection(uuid, uuid, bigint, text, text, text, text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.confirm_cash_collection(uuid, text) TO authenticated;

-- ============================================================================
-- 8. Enhanced Razorpay capture — delegates to allocation engine
-- ============================================================================
CREATE OR REPLACE FUNCTION public.process_razorpay_payment_captured(
  p_razorpay_event_id text,
  p_event_type text,
  p_payload jsonb,
  p_razorpay_payment_id text,
  p_razorpay_order_id text,
  p_amount_paise bigint,
  p_firm_id uuid,
  p_platform_invoice_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_existing uuid;
  v_payment_id uuid;
  v_alloc jsonb;
BEGIN
  SELECT id INTO v_existing FROM public.webhook_events WHERE razorpay_event_id = p_razorpay_event_id;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'duplicate', true);
  END IF;

  INSERT INTO public.webhook_events (razorpay_event_id, event_type, payload, processed)
  VALUES (p_razorpay_event_id, p_event_type, p_payload, false);

  SELECT id INTO v_payment_id FROM public.platform_payments WHERE razorpay_payment_id = p_razorpay_payment_id;
  IF v_payment_id IS NULL THEN
    INSERT INTO public.platform_payments (
      firm_id, platform_invoice_id, razorpay_payment_id, razorpay_order_id,
      amount_paise, currency, status, captured_at, method, metadata
    )
    VALUES (
      p_firm_id, p_platform_invoice_id, p_razorpay_payment_id, p_razorpay_order_id,
      p_amount_paise, 'INR', 'CAPTURED', now(), 'razorpay',
      jsonb_build_object('event_id', p_razorpay_event_id)
    )
    RETURNING id INTO v_payment_id;
  END IF;

  IF p_platform_invoice_id IS NOT NULL THEN
    UPDATE public.platform_invoices
    SET paid_paise = LEAST(total_paise, paid_paise + p_amount_paise),
        status = CASE WHEN paid_paise + p_amount_paise >= total_paise THEN 'paid' ELSE 'partially_paid' END,
        updated_at = now()
    WHERE id = p_platform_invoice_id;

    UPDATE public.razorpay_orders SET status = 'paid' WHERE razorpay_order_id = p_razorpay_order_id;
  END IF;

  v_alloc := public.allocate_platform_invoice_payment(v_payment_id);

  UPDATE public.webhook_events SET processed = true, processed_at = now() WHERE razorpay_event_id = p_razorpay_event_id;

  RETURN jsonb_build_object('ok', true, 'payment_id', v_payment_id, 'allocation', v_alloc);
END;
$$;

-- Credit top-up helper: resolve amount from rate card
CREATE OR REPLACE FUNCTION public.create_credit_topup_invoice(
  p_firm_id uuid,
  p_credits numeric,
  p_wallet_type text DEFAULT 'ai'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org record;
  v_rate bigint;
  v_item_type text;
  v_desc text;
BEGIN
  IF p_firm_id IS DISTINCT FROM public.my_firm_id() AND NOT public.is_saas_admin() THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT name INTO v_org FROM public.organizations WHERE id = p_firm_id;

  SELECT COALESCE((value #>> '{}')::bigint, 100)
  INTO v_rate
  FROM public.platform_settings
  WHERE key = 'billing.credit_unit_price_paise';
  IF v_rate IS NULL OR v_rate <= 0 THEN
    v_rate := 100; -- fallback only when platform setting unset; PO should configure rate card
  END IF;

  v_item_type := CASE WHEN p_wallet_type = 'whatsapp' THEN 'whatsapp_topup' ELSE 'credit_topup' END;
  v_desc := CASE WHEN p_wallet_type = 'whatsapp'
    THEN format('WhatsApp credits top-up — %s units', p_credits)
    ELSE format('AI / Ornexa credits top-up — %s units', p_credits)
  END;

  RETURN public.create_platform_commercial_invoice(
    p_firm_id,
    COALESCE(v_org.name, 'Tenant'),
    jsonb_build_array(jsonb_build_object(
      'item_type', v_item_type,
      'description', v_desc,
      'quantity', p_credits,
      'unit_price_paise', v_rate,
      'tax_rate_pct', 18,
      'metadata', jsonb_build_object('credits', p_credits, 'wallet_type', p_wallet_type, 'rate_card_paise', v_rate)
    )),
    NULL, NULL, 7, NULL, v_item_type
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_credit_topup_invoice(uuid, numeric, text) TO authenticated, service_role;


