-- Firm-scoped dashboard aggregates (index-friendly, same business output).
create or replace function public.get_home_dashboard_summary()
returns table(
  vault_gold_mg bigint,
  karigar_gold_mg bigint,
  finished_gold_mg bigint,
  customer_gold_mg bigint,
  jeweller_gold_mg bigint,
  scrap_gold_mg bigint,
  ledger_discrepancy_mg bigint,
  open_orders bigint,
  total_orders bigint,
  available_stock_count bigint,
  today_billing_paise bigint,
  today_invoice_count bigint,
  total_invoice_count bigint,
  today_cash_paise bigint,
  today_upi_paise bigint,
  today_card_paise bigint,
  today_gold_paid_paise bigint,
  today_outstanding_paise bigint,
  today_gold_sold_mg bigint
)
language sql
stable
security invoker
set search_path = pg_catalog, public
as $$
  with firm as (
    select (select public.my_firm_id()) as firm_id
  ),
  ledger as (
    select
      coalesce(sum((gl.bucket_deltas->>'vault')::bigint), 0)::bigint as vault_mg,
      coalesce(sum((gl.bucket_deltas->>'karigar')::bigint), 0)::bigint as karigar_mg,
      coalesce(sum((gl.bucket_deltas->>'finished')::bigint), 0)::bigint as finished_mg,
      coalesce(sum((gl.bucket_deltas->>'customer')::bigint), 0)::bigint as customer_mg,
      coalesce(sum((gl.bucket_deltas->>'jeweller')::bigint), 0)::bigint as jeweller_mg,
      coalesce(sum((gl.bucket_deltas->>'scrap')::bigint), 0)::bigint as scrap_mg,
      coalesce(sum(gl.net_fine_mg), 0)::bigint as total_mg
    from public.gold_ledger gl, firm f
    where gl.firm_id = f.firm_id
  ),
  today_invoices as (
    select i.*
    from public.invoices i, firm f
    where i.firm_id = f.firm_id
      and i.created_at >= current_date
      and i.created_at < current_date + interval '1 day'
  ),
  payment_totals as (
    select
      coalesce(sum(case when payment->>'mode' = 'cash' then (payment->>'amountPaise')::bigint else 0 end), 0)::bigint as cash_paise,
      coalesce(sum(case when payment->>'mode' = 'upi' then (payment->>'amountPaise')::bigint else 0 end), 0)::bigint as upi_paise,
      coalesce(sum(case when payment->>'mode' = 'card' then (payment->>'amountPaise')::bigint else 0 end), 0)::bigint as card_paise,
      coalesce(sum(case when payment->>'mode' in ('gold_exchange', 'customer_gold_credit') then (payment->>'amountPaise')::bigint else 0 end), 0)::bigint as gold_paid_paise
    from today_invoices ti
    cross join lateral jsonb_array_elements(coalesce(ti.data->'payments', '[]'::jsonb)) payment
  ),
  item_totals as (
    select coalesce(sum((item->>'fineMg')::bigint), 0)::bigint as gold_sold_mg
    from today_invoices ti
    cross join lateral jsonb_array_elements(coalesce(ti.data->'items', '[]'::jsonb)) item
  )
  select
    l.vault_mg,
    l.karigar_mg,
    l.finished_mg,
    l.customer_mg,
    l.jeweller_mg,
    l.scrap_mg,
    (l.total_mg - (l.vault_mg + l.karigar_mg + l.finished_mg + l.customer_mg + l.jeweller_mg + l.scrap_mg))::bigint,
    (select count(*)::bigint from public.orders o, firm f where o.firm_id = f.firm_id and o.status not in ('delivered', 'cancelled')),
    (select count(*)::bigint from public.orders o, firm f where o.firm_id = f.firm_id),
    (select count(*)::bigint from public.inventory inv, firm f where inv.firm_id = f.firm_id and inv.status = 'available'),
    coalesce((select sum(ti.grand_total_paise)::bigint from today_invoices ti), 0)::bigint,
    (select count(*)::bigint from today_invoices),
    (select count(*)::bigint from public.invoices i, firm f where i.firm_id = f.firm_id),
    pt.cash_paise,
    pt.upi_paise,
    pt.card_paise,
    pt.gold_paid_paise,
    coalesce((select sum(greatest(ti.balance_paise, 0))::bigint from today_invoices ti), 0)::bigint,
    it.gold_sold_mg
  from ledger l
  cross join payment_totals pt
  cross join item_totals it;
$$;

revoke all on function public.get_home_dashboard_summary() from public, anon;
grant execute on function public.get_home_dashboard_summary() to authenticated, service_role;


-- ------------------------------------------------------------------------------
-- [192/208] MIGRATION: 20260830160000_document_hosting_retention_and_rate_limits.sql
-- ------------------------------------------------------------------------------

-- Document hosting retention + metadata (1-year default, plan-configurable max).
-- Access still via resolve_document_share RPC — no raw storage URLs.

begin;

create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;

alter table public.document_shares
  add column if not exists party_id text,
  add column if not exists form_metadata jsonb not null default '{}'::jsonb,
  add column if not exists retention_expires_at timestamptz,
  add column if not exists updated_at timestamptz not null default now(),
  add column if not exists share_status text not null default 'active'
    check (share_status in ('active', 'revoked', 'expired', 'archived'));

-- Backfill retention from expires_at for existing rows
update public.document_shares
set retention_expires_at = coalesce(retention_expires_at, expires_at)
where retention_expires_at is null;

-- Default new shares: 1 year access window (matches app DEFAULT_DOCUMENT_HOSTING_DAYS)
alter table public.document_shares
  alter column expires_at set default (now() + interval '365 days');

create index if not exists document_shares_retention_expires_idx
  on public.document_shares (retention_expires_at)
  where share_status = 'active';

create index if not exists document_shares_party_id_idx
  on public.document_shares (party_id)
  where party_id is not null;

-- Lightweight API abuse protection: per-key sliding window (server-side).
create table if not exists public.api_rate_limits (
  id bigserial primary key,
  rate_key text not null,
  window_start timestamptz not null default now(),
  request_count integer not null default 0 check (request_count >= 0),
  constraint api_rate_limits_key_window unique (rate_key, window_start)
);

create index if not exists api_rate_limits_key_start_idx
  on public.api_rate_limits (rate_key, window_start desc);

alter table public.api_rate_limits enable row level security;

-- Only service role / security definer functions may read/write rate limits.
revoke all on public.api_rate_limits from anon, authenticated;

create or replace function public.check_api_rate_limit(
  p_key text,
  p_max_requests integer default 30,
  p_window_seconds integer default 60
)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_window timestamptz;
  v_count integer;
begin
  if p_key is null or length(p_key) < 3 then
    return false;
  end if;
  if p_max_requests < 1 or p_window_seconds < 1 then
    return true;
  end if;

  v_window := date_trunc('minute', now());

  insert into public.api_rate_limits (rate_key, window_start, request_count)
  values (p_key, v_window, 1)
  on conflict (rate_key, window_start)
  do update set request_count = public.api_rate_limits.request_count + 1
  returning request_count into v_count;

  return v_count <= p_max_requests;
end;
$$;

revoke all on function public.check_api_rate_limit(text, integer, integer) from public;
grant execute on function public.check_api_rate_limit(text, integer, integer) to anon, authenticated;

create or replace function public.resolve_document_share(p_token text)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_share public.document_shares;
  v_hash text;
  v_rate_ok boolean;
begin
  if p_token is null or length(p_token) < 48 then
    return null;
  end if;

  v_rate_ok := public.check_api_rate_limit(
    'doc_share:' || left(encode(extensions.digest(p_token::bytea, 'sha256'::text), 'hex'), 16),
    20,
    60
  );
  if not v_rate_ok then
    return null;
  end if;

  v_hash := encode(extensions.digest(p_token::bytea, 'sha256'::text), 'hex');

  select * into v_share
  from public.document_shares
  where token_hash = v_hash
    and revoked_at is null
    and share_status = 'active'
    and expires_at > now()
    and (retention_expires_at is null or retention_expires_at > now())
    and (max_views is null or view_count < max_views)
  for update;

  if not found then
    return null;
  end if;

  update public.document_shares
  set view_count = view_count + 1,
      last_accessed_at = now(),
      updated_at = now()
  where id = v_share.id;

  return jsonb_build_object(
    'id', v_share.id,
    'document_type', v_share.document_type,
    'document_id', v_share.document_id,
    'party_id', v_share.party_id,
    'firm_snapshot', v_share.firm_snapshot,
    'document_snapshot', v_share.document_snapshot,
    'form_metadata', v_share.form_metadata,
    'expires_at', v_share.expires_at,
    'retention_expires_at', v_share.retention_expires_at,
    'created_at', v_share.created_at,
    'branch_id', v_share.branch_id
  );
end;
$$;

revoke all on function public.resolve_document_share(text) from public, authenticated;
grant execute on function public.resolve_document_share(text) to anon;

commit;


-- ------------------------------------------------------------------------------
-- [193/208] MIGRATION: 20260830160000_egress_rate_limit_hot_rpcs.sql
-- ------------------------------------------------------------------------------

-- Server-side rate limits for expensive authenticated RPCs (egress/CPU abuse guard).
-- Does not weaken RLS; per-user buckets only.

create table if not exists public.egress_rate_limit_buckets (
  user_id uuid not null,
  bucket text not null,
  window_start timestamptz not null,
  hit_count int not null default 0,
  primary key (user_id, bucket)
);

alter table public.egress_rate_limit_buckets enable row level security;

revoke all on table public.egress_rate_limit_buckets from public, anon, authenticated;

create or replace function public.enforce_egress_rate_limit(
  p_bucket text,
  p_max_hits int,
  p_window_seconds int
)
returns void
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_uid uuid := auth.uid();
  v_now timestamptz := now();
  v_window timestamptz;
  v_count int;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if p_bucket is null or length(trim(p_bucket)) = 0 then
    raise exception 'invalid rate limit bucket';
  end if;

  select window_start, hit_count
  into v_window, v_count
  from public.egress_rate_limit_buckets
  where user_id = v_uid and bucket = p_bucket
  for update;

  if not found then
    insert into public.egress_rate_limit_buckets (user_id, bucket, window_start, hit_count)
    values (v_uid, p_bucket, v_now, 1);
    return;
  end if;

  if v_window + make_interval(secs => p_window_seconds) <= v_now then
    update public.egress_rate_limit_buckets
    set window_start = v_now, hit_count = 1
    where user_id = v_uid and bucket = p_bucket;
    return;
  end if;

  if v_count >= p_max_hits then
    raise exception 'rate limit exceeded (% per %s)', p_max_hits, p_window_seconds
      using errcode = 'P0001';
  end if;

  update public.egress_rate_limit_buckets
  set hit_count = hit_count + 1
  where user_id = v_uid and bucket = p_bucket;
end;
$$;

revoke all on function public.enforce_egress_rate_limit(text, int, int) from public, anon;
grant execute on function public.enforce_egress_rate_limit(text, int, int) to authenticated, service_role;

-- Gold ledger page RPC (paginated; COUNT skips on timeout)
create or replace function public.get_gold_ledger_page(
  p_bucket text default null,
  p_purity text default null,
  p_type text default null,
  p_from timestamptz default null,
  p_to timestamptz default null,
  p_limit int default 100,
  p_offset int default 0
)
returns jsonb
language plpgsql
stable
security invoker
set search_path = pg_catalog, public
as $$
declare
  v_rows jsonb;
  v_total bigint := -1;
  v_limit int := greatest(1, least(coalesce(p_limit, 100), 500));
  v_offset int := greatest(0, coalesce(p_offset, 0));
begin
  perform public.enforce_egress_rate_limit('rpc:gold_ledger_page', 90, 60);

  select coalesce(jsonb_agg(row_to_json(t)::jsonb order by t.ts asc), '[]'::jsonb)
  into v_rows
  from (
    select gl.id, gl.ts, gl.net_fine_mg, gl.bucket_deltas, gl.data
    from public.gold_ledger gl
    where gl.firm_id = public.my_firm_id()
      and (p_from is null or gl.ts >= p_from)
      and (p_to is null or gl.ts <= p_to)
      and (p_bucket is null or (gl.bucket_deltas ? p_bucket))
      and (p_purity is null or gl.data->>'purity' = p_purity)
      and (p_type is null or gl.data->>'type' = p_type)
    order by gl.ts asc
    limit v_limit
    offset v_offset
  ) t;

  begin
    perform set_config('statement_timeout', '8000', true);
    select count(*) into v_total
    from public.gold_ledger gl
    where gl.firm_id = public.my_firm_id()
      and (p_from is null or gl.ts >= p_from)
      and (p_to is null or gl.ts <= p_to)
      and (p_bucket is null or (gl.bucket_deltas ? p_bucket))
      and (p_purity is null or gl.data->>'purity' = p_purity)
      and (p_type is null or gl.data->>'type' = p_type);
  exception
    when query_canceled then
      v_total := -1;
  end;

  perform set_config('statement_timeout', '0', true);

  return jsonb_build_object('rows', v_rows, 'total', v_total, 'limit', v_limit, 'offset', v_offset);
end;
$$;

-- Authorization context: canonical body + rate limit (120/min per user)
create or replace function public.get_authorization_context()
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public
as $$
declare
  v_uid uuid := auth.uid();
  v_is_platform boolean := false;
  v_active_org uuid;
  v_active_portal text;
  v_active_membership_id uuid;
  v_active_branch text;
  v_pref_org uuid;
  v_pref_portal text;
  v_workspaces jsonb;
  v_active jsonb;
  v_default_route text;
  v_active_type text;
begin
  if v_uid is null then return null; end if;

  perform public.enforce_egress_rate_limit('rpc:auth_context', 120, 60);

  v_is_platform := public.is_saas_admin() or exists (
    select 1 from public.user_roles ur
    where ur.user_id = v_uid
      and ur.role::text in ('saas_admin', 'SaaS Admin', 'platform_owner', 'Platform Owner')
  );

  select last_active_organization_id, last_active_portal_type
  into v_pref_org, v_pref_portal
  from public.user_preferences
  where auth_user_id = v_uid;

  select organization_id, portal_type, membership_id, branch_id
  into v_active_org, v_active_portal, v_active_membership_id, v_active_branch
  from public.identity_active_context
  where auth_user_id = v_uid;

  if v_is_platform and v_active_org is null and v_active_portal is null then
    v_active_type := 'platform';
  elsif v_active_portal is not null then
    v_active_type := v_active_portal;
  elsif v_active_org is not null then
    v_active_type := 'erp';
  else
    v_active_type := null;
  end if;

  select coalesce(jsonb_agg(ws order by ws ->> 'organization_name', ws ->> 'workspace_type'), '[]'::jsonb)
  into v_workspaces
  from (
    select jsonb_build_object(
      'workspace_key', tm.organization_id::text || ':' || public.workspace_type_for_membership(tm),
      'workspace_type', public.workspace_type_for_membership(tm),
      'organization_id', tm.organization_id,
      'organization_name', o.name,
      'membership_id', tm.id,
      'membership_kind', tm.membership_kind,
      'portal_type', tm.portal_type,
      'role', tm.role,
      'branch_ids', tm.branch_ids,
      'party_roles', coalesce((
        select jsonb_agg(distinct pi.portal_type)
        from public.portal_identities pi
        where pi.auth_user_id = v_uid
          and pi.firm_id = tm.organization_id
          and pi.status = 'active'
      ), '[]'::jsonb),
      'route', public.workspace_route_for_membership(tm),
      'is_active',
        tm.organization_id = v_active_org
        and public.workspace_type_for_membership(tm) = coalesce(v_active_type, public.workspace_type_for_membership(tm))
    ) as ws
    from public.tenant_memberships tm
    join public.organizations o on o.id = tm.organization_id
    where tm.auth_user_id = v_uid and tm.status = 'active'
  ) sub;

  if v_is_platform then
    v_workspaces := coalesce(v_workspaces, '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
      'workspace_key', 'platform:platform',
      'workspace_type', 'platform',
      'organization_id', null,
      'organization_name', 'Platform Owner',
      'membership_kind', 'platform',
      'portal_type', null,
      'role', 'saas_admin',
      'route', '/platform',
      'is_active', v_active_type = 'platform'
    ));
  end if;

  select jsonb_build_object(
    'workspace_key',
      case
        when v_active_type = 'platform' then 'platform:platform'
        when v_active_org is not null then v_active_org::text || ':' || coalesce(v_active_type, 'erp')
        else null
      end,
    'workspace_type', coalesce(v_active_type, 'erp'),
    'organization_id', v_active_org,
    'portal_type', v_active_portal,
    'membership_id', v_active_membership_id,
    'branch_id', v_active_branch
  ) into v_active;

  v_default_route := public.resolve_default_workspace_route(v_uid, v_pref_org, v_pref_portal);

  return jsonb_build_object(
    'is_platform_owner', v_is_platform,
    'workspaces', coalesce(v_workspaces, '[]'::jsonb),
    'active_workspace', v_active,
    'default_route', v_default_route,
    'auth_user_id', v_uid
  );
end;
$$;

revoke all on function public.get_authorization_context() from public, anon;
grant execute on function public.get_authorization_context() to authenticated;


-- ------------------------------------------------------------------------------
-- [194/208] MIGRATION: 20260830170000_platform_database_health_observability.sql
-- ------------------------------------------------------------------------------

-- Platform Owner: real database health + egress observability (saas_admin only).
-- Reads live PostgreSQL stats and platform telemetry tables — no fabricated metrics.

begin;

create or replace function public.get_platform_database_health()
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_started timestamptz := clock_timestamp();
  v_ping_ms int;
  v_db_size bigint;
  v_connections int;
  v_errors_1h int;
  v_errors_24h int;
  v_critical_24h int;
  v_orgs int;
  v_active_orgs int;
  v_subs int;
  v_rate_buckets jsonb;
  v_table_stats jsonb;
  v_errors_by_category jsonb;
begin
  if not public.is_saas_admin() then
    raise exception 'platform admin role required' using errcode = '42501';
  end if;

  select pg_database_size(current_database()) into v_db_size;
  select count(*)::int
    into v_connections
    from pg_stat_activity
   where datname = current_database();

  select count(*)::int into v_errors_1h
    from public.platform_error_events
   where created_at > now() - interval '1 hour';

  select count(*)::int into v_errors_24h
    from public.platform_error_events
   where created_at > now() - interval '24 hours';

  select count(*)::int into v_critical_24h
    from public.platform_error_events
   where created_at > now() - interval '24 hours'
     and severity = 'critical';

  select count(*)::int into v_orgs from public.organizations;
  select count(*)::int into v_active_orgs from public.organizations where is_active = true;

  select count(*)::int into v_subs
    from public.subscriptions
   where status in ('active', 'trial', 'trialing', 'TRIAL_ACTIVE', 'ACTIVE');

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'bucket', s.bucket,
        'users', s.user_count,
        'hits', s.total_hits
      )
      order by s.total_hits desc
    ),
    '[]'::jsonb
  )
  into v_rate_buckets
  from (
    select
      bucket,
      count(distinct user_id)::int as user_count,
      sum(hit_count)::int as total_hits
    from public.egress_rate_limit_buckets
    group by bucket
    order by sum(hit_count) desc
    limit 20
  ) s;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'table', t.relname,
        'live_rows', t.n_live_tup,
        'size_bytes', pg_total_relation_size(t.relid)
      )
      order by pg_total_relation_size(t.relid) desc
    ),
    '[]'::jsonb
  )
  into v_table_stats
  from (
    select relname, n_live_tup, relid
    from pg_stat_user_tables
    where schemaname = 'public'
    order by pg_total_relation_size(relid) desc
    limit 12
  ) t;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'category', c.category,
        'count', c.cnt,
        'critical', c.critical_cnt
      )
      order by c.cnt desc
    ),
    '[]'::jsonb
  )
  into v_errors_by_category
  from (
    select
      category,
      count(*)::int as cnt,
      count(*) filter (where severity = 'critical')::int as critical_cnt
    from public.platform_error_events
    where created_at > now() - interval '24 hours'
    group by category
    order by count(*) desc
    limit 15
  ) c;

  v_ping_ms := extract(milliseconds from clock_timestamp() - v_started)::int;

  return jsonb_build_object(
    'ok', true,
    'checked_at', now(),
    'ping_ms', v_ping_ms,
    'database_size_bytes', v_db_size,
    'active_connections', v_connections,
    'errors_last_1h', v_errors_1h,
    'errors_last_24h', v_errors_24h,
    'critical_errors_last_24h', v_critical_24h,
    'errors_by_category_24h', v_errors_by_category,
    'total_organizations', v_orgs,
    'active_organizations', v_active_orgs,
    'active_subscriptions', v_subs,
    'rate_limit_buckets', v_rate_buckets,
    'largest_tables', v_table_stats
  );
end;
$$;

revoke all on function public.get_platform_database_health() from public, anon;
grant execute on function public.get_platform_database_health() to authenticated, service_role;

-- Egress / API pressure observability from DB-visible signals (rate limits + error telemetry).
create or replace function public.get_platform_egress_observability()
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_started timestamptz := clock_timestamp();
  v_rate_total_hits int;
  v_rate_users int;
  v_rate_buckets jsonb;
  v_errors_1h jsonb;
  v_postgres_signals jsonb;
begin
  if not public.is_saas_admin() then
    raise exception 'platform admin role required' using errcode = '42501';
  end if;

  select coalesce(sum(hit_count), 0)::int, count(distinct user_id)::int
    into v_rate_total_hits, v_rate_users
    from public.egress_rate_limit_buckets;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'bucket', bucket,
        'users', user_count,
        'hits', total_hits,
        'window_start', window_start
      )
      order by total_hits desc
    ),
    '[]'::jsonb
  )
  into v_rate_buckets
  from (
    select
      bucket,
      count(distinct user_id)::int as user_count,
      sum(hit_count)::int as total_hits,
      max(window_start) as window_start
    from public.egress_rate_limit_buckets
    group by bucket
    order by sum(hit_count) desc
    limit 30
  ) s;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'hour', date_trunc('hour', created_at),
        'count', cnt,
        'critical', critical_cnt
      )
      order by date_trunc('hour', created_at) desc
    ),
    '[]'::jsonb
  )
  into v_errors_1h
  from (
    select
      date_trunc('hour', created_at) as created_at,
      count(*)::int as cnt,
      count(*) filter (where severity = 'critical')::int as critical_cnt
    from public.platform_error_events
    where created_at > now() - interval '24 hours'
    group by 1
    order by 1 desc
    limit 24
  ) h;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'message', left(message, 200),
        'category', category,
        'severity', severity,
        'created_at', created_at
      )
      order by created_at desc
    ),
    '[]'::jsonb
  )
  into v_postgres_signals
  from (
    select message, category, severity, created_at
    from public.platform_error_events
    where created_at > now() - interval '24 hours'
      and (
        message ilike '%57014%'
        or message ilike '%timeout%'
        or message ilike '%postgres%'
        or message ilike '%PGRST%'
        or message ilike '%rate limit%'
        or category ilike '%database%'
        or category ilike '%supabase%'
      )
    order by created_at desc
    limit 25
  ) e;

  return jsonb_build_object(
    'ok', true,
    'checked_at', now(),
    'query_ms', extract(milliseconds from clock_timestamp() - v_started)::int,
    'rate_limit_total_hits', v_rate_total_hits,
    'rate_limit_distinct_users', v_rate_users,
    'rate_limit_buckets', v_rate_buckets,
    'error_events_by_hour_24h', v_errors_1h,
    'postgres_related_errors_24h', v_postgres_signals,
    'note', 'Supabase REST/Auth/Realtime gateway counts are measured client-side via window.__ORNEXA_EGRESS__ on owner sessions; this RPC reports PostgreSQL-visible pressure (rate limits + error telemetry).'
  );
end;
$$;

revoke all on function public.get_platform_egress_observability() from public, anon;
grant execute on function public.get_platform_egress_observability() to authenticated, service_role;

commit;


-- ------------------------------------------------------------------------------
-- [195/208] MIGRATION: 20260830180000_boot_operational_query_perf.sql
-- ------------------------------------------------------------------------------

-- Boot operational query performance: firm-scoped partial indexes + dashboard RPC hardening.
-- Root cause: unscoped or cross-join COUNT/aggregate paths timed out (57014) under load.

begin;

-- Open-order dashboard counts and bucket queries (firm + status filter).
create index if not exists idx_orders_firm_open_updated
  on public.orders (firm_id, updated_at desc)
  where status not in ('delivered', 'cancelled');

-- Worker transaction pulls filter by firm + kind + recency.
create index if not exists idx_worker_transactions_firm_kind_ts
  on public.worker_transactions (firm_id, kind, ts desc);

-- Dashboard aggregates: single initplan firm_id, index-friendly counts, bounded ledger scan.
create or replace function public.get_home_dashboard_summary()
returns table(
  vault_gold_mg bigint,
  karigar_gold_mg bigint,
  finished_gold_mg bigint,
  customer_gold_mg bigint,
  jeweller_gold_mg bigint,
  scrap_gold_mg bigint,
  ledger_discrepancy_mg bigint,
  open_orders bigint,
  total_orders bigint,
  available_stock_count bigint,
  today_billing_paise bigint,
  today_invoice_count bigint,
  total_invoice_count bigint,
  today_cash_paise bigint,
  today_upi_paise bigint,
  today_card_paise bigint,
  today_gold_paid_paise bigint,
  today_outstanding_paise bigint,
  today_gold_sold_mg bigint
)
language sql
stable
security invoker
set search_path = pg_catalog, public
as $$
  with scope as (
    select (select public.my_firm_id()) as firm_id
  ),
  ledger as (
    select
      coalesce(sum((gl.bucket_deltas->>'vault')::bigint), 0)::bigint as vault_mg,
      coalesce(sum((gl.bucket_deltas->>'karigar')::bigint), 0)::bigint as karigar_mg,
      coalesce(sum((gl.bucket_deltas->>'finished')::bigint), 0)::bigint as finished_mg,
      coalesce(sum((gl.bucket_deltas->>'customer')::bigint), 0)::bigint as customer_mg,
      coalesce(sum((gl.bucket_deltas->>'jeweller')::bigint), 0)::bigint as jeweller_mg,
      coalesce(sum((gl.bucket_deltas->>'scrap')::bigint), 0)::bigint as scrap_mg,
      coalesce(sum(gl.net_fine_mg), 0)::bigint as total_mg
    from public.gold_ledger gl
    cross join scope s
    where gl.firm_id = s.firm_id
  ),
  order_counts as (
    select
      count(*) filter (
        where o.status not in ('delivered', 'cancelled')
      )::bigint as open_cnt,
      count(*)::bigint as total_cnt
    from public.orders o
    cross join scope s
    where o.firm_id = s.firm_id
  ),
  today_invoices as (
    select i.*
    from public.invoices i
    cross join scope s
    where i.firm_id = s.firm_id
      and i.created_at >= current_date
      and i.created_at < current_date + interval '1 day'
  ),
  payment_totals as (
    select
      coalesce(sum(case when payment->>'mode' = 'cash' then (payment->>'amountPaise')::bigint else 0 end), 0)::bigint as cash_paise,
      coalesce(sum(case when payment->>'mode' = 'upi' then (payment->>'amountPaise')::bigint else 0 end), 0)::bigint as upi_paise,
      coalesce(sum(case when payment->>'mode' = 'card' then (payment->>'amountPaise')::bigint else 0 end), 0)::bigint as card_paise,
      coalesce(sum(case when payment->>'mode' in ('gold_exchange', 'customer_gold_credit') then (payment->>'amountPaise')::bigint else 0 end), 0)::bigint as gold_paid_paise
    from today_invoices ti
    cross join lateral jsonb_array_elements(coalesce(ti.data->'payments', '[]'::jsonb)) payment
  ),
  item_totals as (
    select coalesce(sum((item->>'fineMg')::bigint), 0)::bigint as gold_sold_mg
    from today_invoices ti
    cross join lateral jsonb_array_elements(coalesce(ti.data->'items', '[]'::jsonb)) item
  ),
  stock_counts as (
    select count(*)::bigint as available_cnt
    from public.inventory inv
    cross join scope s
    where inv.firm_id = s.firm_id
      and inv.status = 'available'
  ),
  invoice_totals as (
    select count(*)::bigint as total_cnt
    from public.invoices i
    cross join scope s
    where i.firm_id = s.firm_id
  )
  select
    l.vault_mg,
    l.karigar_mg,
    l.finished_mg,
    l.customer_mg,
    l.jeweller_mg,
    l.scrap_mg,
    (l.total_mg - (l.vault_mg + l.karigar_mg + l.finished_mg + l.customer_mg + l.jeweller_mg + l.scrap_mg))::bigint,
    oc.open_cnt,
    oc.total_cnt,
    sc.available_cnt,
    coalesce((select sum(ti.grand_total_paise)::bigint from today_invoices ti), 0)::bigint,
    (select count(*)::bigint from today_invoices),
    it.total_cnt,
    pt.cash_paise,
    pt.upi_paise,
    pt.card_paise,
    pt.gold_paid_paise,
    coalesce((select sum(greatest(ti.balance_paise, 0))::bigint from today_invoices ti), 0)::bigint,
    itt.gold_sold_mg
  from ledger l
  cross join order_counts oc
  cross join stock_counts sc
  cross join invoice_totals it
  cross join payment_totals pt
  cross join item_totals itt;
$$;

