  )
  on conflict (firm_id, doc_type, record_id)
  do update set
    public_token = excluded.public_token,
    token_hash = excluded.token_hash,
    legacy_checksum_token = excluded.legacy_checksum_token,
    status = excluded.status,
    updated_at = now();
end;
$$;

