-- ------------------------------------------------------------------------------
-- [201/208] MIGRATION: 20260830240000_fix_auth_context_readonly_login.sql
-- ------------------------------------------------------------------------------

-- Fix login break: get_authorization_context was STABLE but called enforce_egress_rate_limit
-- (SELECT FOR UPDATE + writes) → PostgREST read-only transaction error 25006 / HTTP 405.
-- Auth credentials were always valid; workspace bootstrap failed after sign-in.
-- Append-only, forward-safe. Does NOT alter user/membership data.

begin;

create or replace function public.get_authorization_context()
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public
as $$
declare
  v_uid uuid := auth.uid();
  v_is_platform boolean := false;
  v_active_org uuid;
  v_active_portal text;
  v_active_membership_id uuid;
  v_active_branch text;
  v_pref_org uuid;
  v_pref_portal text;
  v_workspaces jsonb;
  v_active jsonb;
  v_default_route text;
  v_active_type text;
begin
  if v_uid is null then return null; end if;

  -- Rate limit removed from auth bootstrap — must never block login (see 20260830240000).

  v_is_platform := public.is_saas_admin() or exists (
    select 1 from public.user_roles ur
    where ur.user_id = v_uid
      and ur.role::text in ('saas_admin', 'SaaS Admin', 'platform_owner', 'Platform Owner')
  );

  select last_active_organization_id, last_active_portal_type
  into v_pref_org, v_pref_portal
  from public.user_preferences
  where auth_user_id = v_uid;

  select organization_id, portal_type, membership_id, branch_id
  into v_active_org, v_active_portal, v_active_membership_id, v_active_branch
  from public.identity_active_context
  where auth_user_id = v_uid;

  if v_is_platform and v_active_org is null and v_active_portal is null then
    v_active_type := 'platform';
  elsif v_active_portal is not null then
    v_active_type := v_active_portal;
  elsif v_active_org is not null then
    v_active_type := 'erp';
  else
    v_active_type := null;
  end if;

  select coalesce(jsonb_agg(ws order by ws ->> 'organization_name', ws ->> 'workspace_type'), '[]'::jsonb)
  into v_workspaces
  from (
    select jsonb_build_object(
      'workspace_key', tm.organization_id::text || ':' || public.workspace_type_for_membership(tm),
      'workspace_type', public.workspace_type_for_membership(tm),
      'organization_id', tm.organization_id,
      'organization_name', o.name,
      'membership_id', tm.id,
      'membership_kind', tm.membership_kind,
      'portal_type', tm.portal_type,
      'role', tm.role,
      'branch_ids', tm.branch_ids,
      'party_roles', coalesce((
        select jsonb_agg(distinct pi.portal_type)
        from public.portal_identities pi
        where pi.auth_user_id = v_uid
          and pi.firm_id = tm.organization_id
          and pi.status = 'active'
      ), '[]'::jsonb),
      'route', public.workspace_route_for_membership(tm),
      'is_active',
        tm.organization_id = v_active_org
        and public.workspace_type_for_membership(tm) = coalesce(v_active_type, public.workspace_type_for_membership(tm))
    ) as ws
    from public.tenant_memberships tm
    join public.organizations o on o.id = tm.organization_id
    where tm.auth_user_id = v_uid and tm.status = 'active'
  ) sub;

  if v_is_platform then
    v_workspaces := coalesce(v_workspaces, '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
      'workspace_key', 'platform:platform',
      'workspace_type', 'platform',
      'organization_id', null,
      'organization_name', 'Platform Owner',
      'membership_kind', 'platform',
      'portal_type', null,
      'role', 'saas_admin',
      'route', '/platform',
      'is_active', v_active_type = 'platform'
    ));
  end if;

  select jsonb_build_object(
    'workspace_key',
      case
        when v_active_type = 'platform' then 'platform:platform'
        when v_active_org is not null then v_active_org::text || ':' || coalesce(v_active_type, 'erp')
        else null
      end,
    'workspace_type', coalesce(v_active_type, 'erp'),
    'organization_id', v_active_org,
    'portal_type', v_active_portal,
    'membership_id', v_active_membership_id,
    'branch_id', v_active_branch
  ) into v_active;

  v_default_route := public.resolve_default_workspace_route(v_uid, v_pref_org, v_pref_portal);

  return jsonb_build_object(
    'is_platform_owner', v_is_platform,
    'workspaces', coalesce(v_workspaces, '[]'::jsonb),
    'active_workspace', v_active,
    'default_route', v_default_route,
    'auth_user_id', v_uid
  );
end;
$$;

revoke all on function public.get_authorization_context() from public, anon;
grant execute on function public.get_authorization_context() to authenticated;

commit;


-- ------------------------------------------------------------------------------
-- [202/208] MIGRATION: 20260830250000_platform_workspace_role_parity.sql
-- ------------------------------------------------------------------------------

-- Align set_platform_workspace with get_authorization_context platform detection.
-- platform_owner / Platform Owner roles must activate platform workspace (not only saas_admin enum).
-- Append-only, forward-safe. Does NOT alter user/membership data.

begin;

create or replace function public.is_platform_operator()
returns boolean
language sql
stable
security definer
set search_path = pg_catalog, public
as $$
  select
    public.is_saas_admin()
    or exists (
      select 1
      from public.user_roles ur
      where ur.user_id = auth.uid()
        and ur.role::text in (
          'saas_admin',
          'SaaS Admin',
          'platform_owner',
          'Platform Owner'
        )
    );
$$;

revoke all on function public.is_platform_operator() from public, anon;
grant execute on function public.is_platform_operator() to authenticated, service_role;

create or replace function public.set_platform_workspace()
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if not public.is_platform_operator() then
    raise exception 'Platform admin role required' using errcode = '42501';
  end if;

  delete from public.identity_active_context where auth_user_id = auth.uid();

  insert into public.user_preferences (
    auth_user_id,
    last_active_organization_id,
    last_active_portal_type,
    updated_at
  )
  values (auth.uid(), null, null, now())
  on conflict (auth_user_id) do update set
    last_active_organization_id = null,
    last_active_portal_type = null,
    updated_at = now();

  return jsonb_build_object('workspace_type', 'platform', 'route', '/platform');
end;
$$;

revoke all on function public.set_platform_workspace() from public, anon;
grant execute on function public.set_platform_workspace() to authenticated;

commit;


-- ------------------------------------------------------------------------------
-- [203/208] MIGRATION: 20260830260000_fix_auth_context_infer_active_workspace.sql
-- ------------------------------------------------------------------------------

-- Infer default active workspace when identity_active_context is empty.
-- Portal-only users were getting active_workspace.workspace_type='erp' with no is_active
-- rows → canAccessPath denied /karigar-portal, /customer-portal, etc.
-- Append-only, forward-safe. Does NOT alter user/membership data.

begin;

create or replace function public.get_authorization_context()
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public
as $$
declare
  v_uid uuid := auth.uid();
  v_is_platform boolean := false;
  v_active_org uuid;
  v_active_portal text;
  v_active_membership_id uuid;
  v_active_branch text;
  v_pref_org uuid;
  v_pref_portal text;
  v_workspaces jsonb;
  v_active jsonb;
  v_default_route text;
  v_active_type text;
begin
  if v_uid is null then return null; end if;

  v_is_platform := public.is_platform_operator();

  select last_active_organization_id, last_active_portal_type
  into v_pref_org, v_pref_portal
  from public.user_preferences
  where auth_user_id = v_uid;

  select organization_id, portal_type, membership_id, branch_id
  into v_active_org, v_active_portal, v_active_membership_id, v_active_branch
  from public.identity_active_context
  where auth_user_id = v_uid;

  -- No explicit active context: infer from preferences or default membership.
  if v_active_org is null and not v_is_platform then
    if v_pref_org is not null then
      select tm.organization_id, tm.portal_type, tm.id, coalesce(tm.branch_ids[1], null)
      into v_active_org, v_active_portal, v_active_membership_id, v_active_branch
      from public.tenant_memberships tm
      where tm.auth_user_id = v_uid
        and tm.status = 'active'
        and tm.organization_id = v_pref_org
        and (
          v_pref_portal is null
          or tm.portal_type = v_pref_portal
          or (v_pref_portal = 'erp' and tm.membership_kind = 'internal')
        )
      order by
        case
          when v_pref_portal is not null and tm.portal_type = v_pref_portal then 0
          when v_pref_portal = 'erp' and tm.membership_kind = 'internal' then 0
          else 1
        end,
        tm.last_active_at desc nulls last
      limit 1;
    end if;

    if v_active_org is null then
      select tm.organization_id, tm.portal_type, tm.id, coalesce(tm.branch_ids[1], null)
      into v_active_org, v_active_portal, v_active_membership_id, v_active_branch
      from public.tenant_memberships tm
      where tm.auth_user_id = v_uid and tm.status = 'active'
      order by
        case when tm.membership_kind = 'internal' then 0 else 1 end,
        case tm.portal_type
          when 'ceo' then 1
          when 'customer' then 2
          when 'supplier' then 3
          when 'karigar' then 4
          else 9
        end,
        tm.last_active_at desc nulls last,
        tm.joined_at desc
      limit 1;
    end if;
  end if;

  if v_is_platform and v_active_org is null and v_active_portal is null then
    v_active_type := 'platform';
  elsif v_active_portal is not null then
    v_active_type := v_active_portal;
  elsif v_active_org is not null then
    v_active_type := 'erp';
  else
    v_active_type := null;
  end if;

  select coalesce(jsonb_agg(ws order by ws ->> 'organization_name', ws ->> 'workspace_type'), '[]'::jsonb)
  into v_workspaces
  from (
    select jsonb_build_object(
      'workspace_key', tm.organization_id::text || ':' || public.workspace_type_for_membership(tm),
      'workspace_type', public.workspace_type_for_membership(tm),
      'organization_id', tm.organization_id,
      'organization_name', o.name,
      'membership_id', tm.id,
      'membership_kind', tm.membership_kind,
      'portal_type', tm.portal_type,
      'role', tm.role,
      'branch_ids', tm.branch_ids,
      'party_roles', coalesce((
        select jsonb_agg(distinct pi.portal_type)
        from public.portal_identities pi
        where pi.auth_user_id = v_uid
          and pi.firm_id = tm.organization_id
          and pi.status = 'active'
      ), '[]'::jsonb),
      'route', public.workspace_route_for_membership(tm),
      'is_active',
        tm.organization_id = v_active_org
        and public.workspace_type_for_membership(tm) = coalesce(
          v_active_type,
          public.workspace_type_for_membership(tm)
        )
    ) as ws
    from public.tenant_memberships tm
    join public.organizations o on o.id = tm.organization_id
    where tm.auth_user_id = v_uid and tm.status = 'active'
  ) sub;

  if v_is_platform then
    v_workspaces := coalesce(v_workspaces, '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
      'workspace_key', 'platform:platform',
      'workspace_type', 'platform',
      'organization_id', null,
      'organization_name', 'Platform Owner',
      'membership_kind', 'platform',
      'portal_type', null,
      'role', 'saas_admin',
      'route', '/platform',
      'is_active', v_active_type = 'platform'
    ));
  end if;

  select jsonb_build_object(
    'workspace_key',
      case
        when v_active_type = 'platform' then 'platform:platform'
        when v_active_org is not null then v_active_org::text || ':' || coalesce(v_active_type, 'erp')
        else null
      end,
    'workspace_type', coalesce(v_active_type, 'erp'),
    'organization_id', v_active_org,
    'portal_type', v_active_portal,
    'membership_id', v_active_membership_id,
    'branch_id', v_active_branch
  ) into v_active;

  v_default_route := public.resolve_default_workspace_route(v_uid, v_pref_org, v_pref_portal);

  return jsonb_build_object(
    'is_platform_owner', v_is_platform,
    'workspaces', coalesce(v_workspaces, '[]'::jsonb),
    'active_workspace', v_active,
    'default_route', v_default_route,
    'auth_user_id', v_uid
  );
end;
$$;

-- Update get_authorization_context to use is_platform_operator (must exist from 20260830250000).
-- Re-apply grants after replace.
revoke all on function public.get_authorization_context() from public, anon;
grant execute on function public.get_authorization_context() to authenticated;

commit;


-- ------------------------------------------------------------------------------
-- [204/208] MIGRATION: 20260830270000_fix_stable_rpc_rate_limit_readonly.sql
-- ------------------------------------------------------------------------------

-- STABLE RPCs cannot call enforce_egress_rate_limit (writes + FOR UPDATE) inside
-- PostgREST read-only transactions → PostgreSQL 25006 / HTTP 405.
-- Same class of bug as get_authorization_context (20260830240000).
-- Fix: mark rate-limited read RPCs VOLATILE; rate limiter uses upsert (no FOR UPDATE).

begin;

create or replace function public.enforce_egress_rate_limit(
  p_bucket text,
  p_max_hits int,
  p_window_seconds int
)
returns void
language plpgsql
volatile
security definer
set search_path = pg_catalog, public
as $$
declare
  v_uid uuid := auth.uid();
  v_now timestamptz := now();
  v_window timestamptz;
  v_count int;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if p_bucket is null or length(trim(p_bucket)) = 0 then
    raise exception 'invalid rate limit bucket';
  end if;

  insert into public.egress_rate_limit_buckets (user_id, bucket, window_start, hit_count)
  values (v_uid, p_bucket, v_now, 1)
  on conflict (user_id, bucket) do update
  set
    window_start = case
      when public.egress_rate_limit_buckets.window_start + make_interval(secs => p_window_seconds) <= v_now
        then v_now
      else public.egress_rate_limit_buckets.window_start
    end,
    hit_count = case
      when public.egress_rate_limit_buckets.window_start + make_interval(secs => p_window_seconds) <= v_now
        then 1
      else public.egress_rate_limit_buckets.hit_count + 1
    end
  returning window_start, hit_count into v_window, v_count;

  if v_window + make_interval(secs => p_window_seconds) > v_now and v_count > p_max_hits then
    raise exception 'rate limit exceeded (% per %s)', p_max_hits, p_window_seconds
      using errcode = 'P0001';
  end if;
end;
$$;

-- get_gold_ledger_page: STABLE → VOLATILE (rate limit writes)
create or replace function public.get_gold_ledger_page(
  p_bucket text default null,
  p_purity text default null,
  p_type text default null,
  p_from timestamptz default null,
  p_to timestamptz default null,
  p_limit int default 100,
  p_offset int default 0,
  p_order text default 'asc'
)
returns jsonb
language plpgsql
volatile
security invoker
set search_path = pg_catalog, public
as $$
declare
  v_rows jsonb;
  v_total bigint := -1;
  v_limit int := greatest(1, least(coalesce(p_limit, 100), 500));
  v_offset int := greatest(0, coalesce(p_offset, 0));
  v_desc boolean := lower(coalesce(p_order, 'asc')) = 'desc';
begin
  perform public.enforce_egress_rate_limit('rpc:gold_ledger_page', 90, 60);

  if v_desc then
    select coalesce(jsonb_agg(row_to_json(t)::jsonb order by t.ts desc), '[]'::jsonb)
    into v_rows
    from (
      select gl.id, gl.ts, gl.net_fine_mg, gl.bucket_deltas, gl.data
      from public.gold_ledger gl
      where gl.firm_id = public.my_firm_id()
        and (p_from is null or gl.ts >= p_from)
        and (p_to is null or gl.ts <= p_to)
        and (p_bucket is null or (gl.bucket_deltas ? p_bucket))
        and (p_purity is null or gl.data->>'purity' = p_purity)
        and (p_type is null or gl.data->>'type' = p_type)
      order by gl.ts desc
      limit v_limit
      offset v_offset
    ) t;
  else
    select coalesce(jsonb_agg(row_to_json(t)::jsonb order by t.ts asc), '[]'::jsonb)
    into v_rows
    from (
      select gl.id, gl.ts, gl.net_fine_mg, gl.bucket_deltas, gl.data
      from public.gold_ledger gl
      where gl.firm_id = public.my_firm_id()
        and (p_from is null or gl.ts >= p_from)
        and (p_to is null or gl.ts <= p_to)
        and (p_bucket is null or (gl.bucket_deltas ? p_bucket))
        and (p_purity is null or gl.data->>'purity' = p_purity)
        and (p_type is null or gl.data->>'type' = p_type)
      order by gl.ts asc
      limit v_limit
      offset v_offset
    ) t;
  end if;

  if v_offset = 0 then
    begin
      perform set_config('statement_timeout', '8000', true);
      select count(*) into v_total
      from public.gold_ledger gl
      where gl.firm_id = public.my_firm_id()
        and (p_from is null or gl.ts >= p_from)
        and (p_to is null or gl.ts <= p_to)
        and (p_bucket is null or (gl.bucket_deltas ? p_bucket))
        and (p_purity is null or gl.data->>'purity' = p_purity)
        and (p_type is null or gl.data->>'type' = p_type);
    exception
      when query_canceled then
        v_total := -1;
    end;
    perform set_config('statement_timeout', '0', true);
  end if;

  return jsonb_build_object('rows', v_rows, 'total', v_total, 'limit', v_limit, 'offset', v_offset);
end;
$$;

-- get_firm_ledger_balances: STABLE → VOLATILE
create or replace function public.get_firm_ledger_balances(
  p_branch_id text default null,
  p_metal_code text default 'gold'
)
returns jsonb
language plpgsql
volatile
security invoker
set search_path = pg_catalog, public
as $$
declare
  v_firm uuid := public.my_firm_id();
  v_vault bigint := 0;
  v_karigar bigint := 0;
  v_finished bigint := 0;
  v_customer bigint := 0;
  v_jeweller bigint := 0;
  v_scrap bigint := 0;
  v_ledger_total bigint := 0;
  v_entry_count bigint := 0;
begin
  if v_firm is null then
    return jsonb_build_object(
      'buckets', jsonb_build_object(
        'vault', 0, 'karigar', 0, 'finished', 0,
        'customer', 0, 'jeweller', 0, 'scrap', 0
      ),
      'ledgerTotal', 0,
      'entryCount', 0,
      'totalUnderManagement', 0,
      'discrepancyMg', 0,
      'balanced', true
    );
  end if;

  perform public.enforce_egress_rate_limit('rpc:firm_ledger_balances', 60, 60);

  select
    coalesce(sum(coalesce((gl.bucket_deltas->>'vault')::bigint, 0)), 0),
    coalesce(sum(coalesce((gl.bucket_deltas->>'karigar')::bigint, 0)), 0),
    coalesce(sum(coalesce((gl.bucket_deltas->>'finished')::bigint, 0)), 0),
    coalesce(sum(coalesce((gl.bucket_deltas->>'customer')::bigint, 0)), 0),
    coalesce(sum(coalesce((gl.bucket_deltas->>'jeweller')::bigint, 0)), 0),
    coalesce(sum(coalesce((gl.bucket_deltas->>'scrap')::bigint, 0)), 0),
    coalesce(sum(gl.net_fine_mg), 0),
    count(*)
  into v_vault, v_karigar, v_finished, v_customer, v_jeweller, v_scrap, v_ledger_total, v_entry_count
  from public.gold_ledger gl
  where gl.firm_id = v_firm
    and (p_branch_id is null or p_branch_id = 'all' or gl.data->>'branchId' = p_branch_id);

  return jsonb_build_object(
    'buckets', jsonb_build_object(
      'vault', v_vault,
      'karigar', v_karigar,
      'finished', v_finished,
      'customer', v_customer,
      'jeweller', v_jeweller,
      'scrap', v_scrap
    ),
    'ledgerTotal', v_ledger_total,
    'entryCount', v_entry_count,
    'totalUnderManagement', v_vault + v_karigar + v_finished + v_customer + v_jeweller + v_scrap,
    'discrepancyMg', (v_vault + v_karigar + v_finished + v_customer + v_jeweller + v_scrap) - v_ledger_total,
    'balanced', (v_vault + v_karigar + v_finished + v_customer + v_jeweller + v_scrap) = v_ledger_total
  );
end;
$$;

-- Remaining rate-limited RPCs from 20260830210000: STABLE → VOLATILE
create or replace function public.get_billing_outstanding_summary(p_branch_id text default null)
returns table (
  customer_id text,
  customer_name text,
  phone text,
  amount_paise bigint,
  oldest_created_at timestamptz,
  latest_invoice_id text,
  latest_invoice_no text
)
language plpgsql
security invoker
volatile
set search_path = pg_catalog, public
as $$
begin
  perform public.enforce_egress_rate_limit('rpc:billing_outstanding', 40, 60);
  return query
  with open_invoices as (
    select
      i.id,
      i.invoice_no,
      i.customer_id,
      coalesce(nullif(i.data->>'customerName', ''), 'Walk-in Customer') as customer_name,
      nullif(i.data->>'customerPhone', '') as phone,
      i.balance_paise,
      i.created_at,
      row_number() over (
        partition by i.customer_id
        order by i.created_at desc, i.invoice_no desc
      ) as rn
    from public.invoices i
    where i.firm_id = public.my_firm_id()
      and i.status <> 'cancelled'
      and i.balance_paise > 0
      and (p_branch_id is null or i.data->>'branchId' = p_branch_id)
  )
  select
    coalesce(open_invoices.customer_id, 'walk_in')::text,
    max(open_invoices.customer_name)::text,
    max(open_invoices.phone)::text,
    sum(open_invoices.balance_paise)::bigint,
    min(open_invoices.created_at),
    max(open_invoices.id) filter (where open_invoices.rn = 1)::text,
    max(open_invoices.invoice_no) filter (where open_invoices.rn = 1)::text
  from open_invoices
  group by coalesce(open_invoices.customer_id, 'walk_in')
  order by sum(open_invoices.balance_paise) desc;
end;
$$;

create or replace function public.get_company_cash_ledger_page(
  p_account_id text default null,
  p_party_id text default null,
  p_source text default null,
  p_from date default null,
  p_to date default null,
  p_limit int default 100,
  p_offset int default 0
)
returns jsonb
language plpgsql
volatile
security invoker
set search_path = pg_catalog, public
as $$
declare
  v_rows jsonb;
  v_total bigint;
begin
  perform public.enforce_egress_rate_limit('rpc:cash_ledger_page', 60, 60);

  select count(*) into v_total
  from public.universal_ledger_entries u
  where u.firm_id = public.my_firm_id()
    and u.reversal_ref_id is null
    and (u.cash_debit_paise > 0 or u.cash_credit_paise > 0)
    and (p_party_id is null or u.counterparty_id = p_party_id)
    and (p_source is null or u.metadata->>'source' = p_source)
    and (p_from is null or u.voucher_date::date >= p_from)
    and (p_to is null or u.voucher_date::date <= p_to)
    and (
      p_account_id is null
      or u.metadata->>'cash_or_bank_account_id' = p_account_id
      or u.metadata->>'debit_account_id' = p_account_id
      or u.metadata->>'credit_account_id' = p_account_id
      or u.metadata->>'from_account_id' = p_account_id
      or u.metadata->>'to_account_id' = p_account_id
    );

  select coalesce(jsonb_agg(row_to_json(t)::jsonb order by t.voucher_date asc, t.created_at asc), '[]'::jsonb)
  into v_rows
  from (
    select
      u.id,
      u.voucher_number,
      u.voucher_date::date as voucher_date,
      u.counterparty_id,
      u.counterparty_name,
      u.cash_debit_paise,
      u.cash_credit_paise,
      u.metadata,
      u.created_by,
      u.created_at
    from public.universal_ledger_entries u
    where u.firm_id = public.my_firm_id()
      and u.reversal_ref_id is null
      and (u.cash_debit_paise > 0 or u.cash_credit_paise > 0)
      and (p_party_id is null or u.counterparty_id = p_party_id)
      and (p_source is null or u.metadata->>'source' = p_source)
      and (p_from is null or u.voucher_date::date >= p_from)
      and (p_to is null or u.voucher_date::date <= p_to)
      and (
        p_account_id is null
        or u.metadata->>'cash_or_bank_account_id' = p_account_id
        or u.metadata->>'debit_account_id' = p_account_id
        or u.metadata->>'credit_account_id' = p_account_id
        or u.metadata->>'from_account_id' = p_account_id
        or u.metadata->>'to_account_id' = p_account_id
      )
    order by u.voucher_date asc, u.created_at asc
    limit greatest(1, least(p_limit, 500))
    offset greatest(0, p_offset)
  ) t;

  return jsonb_build_object('rows', v_rows, 'total', v_total, 'limit', p_limit, 'offset', p_offset);
end;
$$;

create or replace function public.get_ceo_branch_kpis(p_branch_id text)
returns table (
  sales_this_month_paise bigint,
  invoice_count bigint,
  outstanding_paise bigint,
  pending_orders bigint,
  active_job_cards bigint,
  ready_job_cards bigint,
  pending_repairs bigint,
  total_customers bigint
)
language plpgsql
volatile
security invoker
set search_path = pg_catalog, public
as $$
begin
  perform public.enforce_egress_rate_limit('rpc:ceo_branch_kpis', 30, 60);
  return query
  with params as (
    select
      nullif(p_branch_id, '') as branch_id,
      date_trunc('month', now()) as month_start
  ),
  month_invoices as (
    select
      coalesce(sum(coalesce(i.grand_total_paise, 0)), 0)::bigint as sales_this_month_paise,
      count(*)::bigint as invoice_count
    from public.invoices i, params p
    where i.firm_id = public.my_firm_id()
      and coalesce(i.data->>'branchId', 'MAIN') = coalesce(p.branch_id, 'MAIN')
      and i.created_at >= p.month_start
      and coalesce(i.status, i.data->>'status', '') <> 'cancelled'
  ),
  outstanding_invoices as (
    select coalesce(sum(greatest(coalesce(i.balance_paise, 0), 0)), 0)::bigint as outstanding_paise
    from public.invoices i, params p
    where i.firm_id = public.my_firm_id()
      and coalesce(i.data->>'branchId', 'MAIN') = coalesce(p.branch_id, 'MAIN')
      and coalesce(i.status, i.data->>'status', '') <> 'cancelled'
      and coalesce(i.balance_paise, 0) > 0
  ),
  order_counts as (
    select count(*)::bigint as pending_orders
    from public.orders o, params p
    where o.firm_id = public.my_firm_id()
      and coalesce(o.data->>'branchId', 'MAIN') = coalesce(p.branch_id, 'MAIN')
      and coalesce(o.status, o.data->>'status', '') in ('pending', 'in_progress', 'ready')
  ),
  job_counts as (
    select
      count(*) filter (
        where coalesce(j.status, j.data->>'status', '') in ('open', 'in_progress')
      )::bigint as active_job_cards,
      count(*) filter (
        where coalesce(j.status, j.data->>'status', '') in ('ready', 'ready_for_billing')
      )::bigint as ready_job_cards
    from public.job_cards j, params p
    where j.firm_id = public.my_firm_id()
      and coalesce(j.data->>'branchId', 'MAIN') = coalesce(p.branch_id, 'MAIN')
      and coalesce(j.status, j.data->>'status', '') not in ('closed', 'completed', 'cancelled', 'delivered')
  ),
  repair_counts as (
    select count(*)::bigint as pending_repairs
    from public.repairs r, params p
    where r.firm_id = public.my_firm_id()
      and coalesce(r.data->>'branchId', 'MAIN') = coalesce(p.branch_id, 'MAIN')
      and coalesce(r.status, r.data->>'status', '') not in ('delivered', 'cancelled')
  ),
  customer_counts as (
    select count(*)::bigint as total_customers
    from public.people pe, params p
    where pe.firm_id = public.my_firm_id()
      and coalesce(pe.data->>'branchId', 'MAIN') = coalesce(p.branch_id, 'MAIN')
      and coalesce(pe.type, pe.data->>'type', '') = 'customer'
  )
  select
    month_invoices.sales_this_month_paise,
    month_invoices.invoice_count,
    outstanding_invoices.outstanding_paise,
    order_counts.pending_orders,
    job_counts.active_job_cards,
    job_counts.ready_job_cards,
    repair_counts.pending_repairs,
    customer_counts.total_customers
  from month_invoices, outstanding_invoices, order_counts, job_counts, repair_counts, customer_counts;
end;
$$;

commit;


-- ------------------------------------------------------------------------------
-- [205/208] MIGRATION: 20260830280000_item_groups_and_inventory_master_link.sql
-- ------------------------------------------------------------------------------

-- Item Groups master + inventory ↔ item_masters authority link
-- Forward-safe, RLS-aware (ITEM_AND_MATERIAL_MASTER.md §2.1)

CREATE TABLE IF NOT EXISTS public.item_groups (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  firm_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  group_code text NOT NULL,
  group_name text NOT NULL,
  description text,
  sort_order integer NOT NULL DEFAULT 0,
  is_active boolean NOT NULL DEFAULT true,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT item_groups_firm_code_unique UNIQUE (firm_id, group_code)
);

CREATE INDEX IF NOT EXISTS idx_item_groups_firm ON public.item_groups (firm_id);
CREATE INDEX IF NOT EXISTS idx_item_groups_firm_active ON public.item_groups (firm_id, is_active);

ALTER TABLE public.item_groups ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS item_groups_tenant_select ON public.item_groups;
CREATE POLICY item_groups_tenant_select ON public.item_groups
  FOR SELECT TO authenticated
  USING (
    public.is_saas_admin()
    OR firm_id = public.my_firm_id()
    OR (firm_id IS NULL AND public.my_firm_id() IS NULL)
  );

DROP POLICY IF EXISTS item_groups_tenant_write ON public.item_groups;
CREATE POLICY item_groups_tenant_write ON public.item_groups
  FOR ALL TO authenticated
  USING (
    public.is_saas_admin()
    OR (firm_id = public.my_firm_id() AND NOT public.is_customer_role())
  )
  WITH CHECK (
    public.is_saas_admin()
    OR (firm_id = public.my_firm_id() AND NOT public.is_customer_role())
  );

DROP TRIGGER IF EXISTS trg_item_groups_uat ON public.item_groups;
CREATE TRIGGER trg_item_groups_uat
  BEFORE UPDATE ON public.item_groups
  FOR EACH ROW
  EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.item_masters
  ADD COLUMN IF NOT EXISTS item_group_id text REFERENCES public.item_groups(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_item_masters_group_id
  ON public.item_masters (item_group_id)
  WHERE item_group_id IS NOT NULL;

ALTER TABLE public.inventory
  ADD COLUMN IF NOT EXISTS item_master_id text REFERENCES public.item_masters(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_inventory_item_master_id
  ON public.inventory (item_master_id)
  WHERE item_master_id IS NOT NULL;


